CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='sinex_writer') THEN CREATE ROLE sinex_writer; END IF; IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='sinex_reader') THEN CREATE ROLE sinex_reader; END IF; END $$;
CREATE SCHEMA sinex_schema;
CREATE SCHEMA core;
CREATE SCHEMA audit;
CREATE SCHEMA raw;
CREATE SCHEMA registry;
CREATE SCHEMA derivation;
CREATE SCHEMA privacy;
CREATE SCHEMA telemetry;
CREATE SCHEMA event_types;
CREATE TABLE sinex_schema.applied (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.events (
  id uuid NOT NULL,
  event_type text NOT NULL,
  source text NOT NULL,
  run_id uuid NOT NULL,
  material_id uuid,
  anchor bigint,
  output_index smallint NOT NULL DEFAULT 0,
  parents uuid[],
  ts_orig timestamptz,
  ts_quality text NOT NULL CHECK (ts_quality IN ('intrinsic', 'captured', 'file_mtime', 'operator', 'unknown')),
  ts_coided timestamptz GENERATED ALWAYS AS (uuid_extract_timestamp(id)) STORED,
  ts_persisted timestamptz NOT NULL DEFAULT now(),
  commit_seq bigint NOT NULL,
  payload jsonb NOT NULL,
  equivalence_key text,
  reading_order bigint NOT NULL,
  record_hash bytea NOT NULL,
  record_state text NOT NULL DEFAULT 'present' CHECK (record_state IN ('present', 'removed')),
  class text NOT NULL DEFAULT 'open' CHECK (class IN ('open', 'guarded', 'sealed')),
  CONSTRAINT one_origin CHECK ((material_id IS NOT NULL AND anchor IS NOT NULL AND parents IS NULL) OR (material_id IS NULL AND anchor IS NULL AND parents IS NOT NULL AND cardinality(parents) > 0)),
  CONSTRAINT id_is_uuidv7 CHECK (uuid_extract_version(id) = 7),
  CONSTRAINT time_pair CHECK ((ts_orig IS NULL) = (ts_quality = 'unknown')),
  CONSTRAINT anchor_in_range CHECK (anchor IS NULL OR anchor >= 0),
  CONSTRAINT output_index_in_range CHECK (output_index >= 0),
  CONSTRAINT payload_object CHECK (jsonb_typeof(payload) = 'object'),
  CONSTRAINT hash_length CHECK (length(record_hash) = 32),
  PRIMARY KEY (id)
);
CREATE TABLE telemetry.events (
  id uuid NOT NULL,
  event_type text NOT NULL,
  source text NOT NULL,
  run_id uuid NOT NULL,
  material_id uuid,
  anchor bigint,
  output_index smallint NOT NULL DEFAULT 0,
  parents uuid[],
  ts_orig timestamptz,
  ts_quality text NOT NULL CHECK (ts_quality IN ('intrinsic', 'captured', 'file_mtime', 'operator', 'unknown')),
  ts_coided timestamptz GENERATED ALWAYS AS (uuid_extract_timestamp(id)) STORED,
  ts_persisted timestamptz NOT NULL DEFAULT now(),
  commit_seq bigint NOT NULL,
  payload jsonb NOT NULL,
  equivalence_key text,
  reading_order bigint NOT NULL,
  record_hash bytea NOT NULL,
  record_state text NOT NULL DEFAULT 'present' CHECK (record_state IN ('present', 'removed')),
  class text NOT NULL DEFAULT 'open' CHECK (class IN ('open', 'guarded', 'sealed')),
  CONSTRAINT one_origin CHECK ((material_id IS NOT NULL AND anchor IS NOT NULL AND parents IS NULL) OR (material_id IS NULL AND anchor IS NULL AND parents IS NOT NULL AND cardinality(parents) > 0)),
  CONSTRAINT id_is_uuidv7 CHECK (uuid_extract_version(id) = 7),
  CONSTRAINT time_pair CHECK ((ts_orig IS NULL) = (ts_quality = 'unknown')),
  CONSTRAINT anchor_in_range CHECK (anchor IS NULL OR anchor >= 0),
  CONSTRAINT output_index_in_range CHECK (output_index >= 0),
  CONSTRAINT payload_object CHECK (jsonb_typeof(payload) = 'object'),
  CONSTRAINT hash_length CHECK (length(record_hash) = 32),
  PRIMARY KEY (id)
);
CREATE TABLE core.live_locations (
  material_id uuid NOT NULL,
  anchor bigint NOT NULL,
  event_type text NOT NULL,
  output_index smallint NOT NULL,
  event_id uuid NOT NULL,
  reading_order bigint NOT NULL,
  record_hash bytea NOT NULL,
  PRIMARY KEY (material_id, anchor, event_type, output_index)
);
CREATE TABLE core.live_equivalence (
  source text NOT NULL,
  event_type text NOT NULL,
  equivalence_key text NOT NULL,
  event_id uuid NOT NULL,
  reading_order bigint NOT NULL,
  record_hash bytea NOT NULL,
  PRIMARY KEY (source, event_type, equivalence_key)
);
CREATE INDEX live_equivalence_event ON core.live_equivalence (event_id);
CREATE INDEX live_locations_event ON core.live_locations (event_id);
CREATE TABLE core.hidden_records (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source text NOT NULL,
  event_type text NOT NULL,
  equivalence_key text,
  material_id uuid,
  anchor bigint,
  output_index smallint,
  operation_id uuid NOT NULL,
  hidden_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT keyed_or_located CHECK ((equivalence_key IS NOT NULL AND material_id IS NULL AND anchor IS NULL AND output_index IS NULL) OR (equivalence_key IS NULL AND material_id IS NOT NULL AND anchor IS NOT NULL AND output_index IS NOT NULL))
);
CREATE UNIQUE INDEX hidden_by_key ON core.hidden_records (source, event_type, equivalence_key) WHERE equivalence_key IS NOT NULL;
CREATE UNIQUE INDEX hidden_by_location ON core.hidden_records (material_id, anchor, event_type, output_index) WHERE material_id IS NOT NULL;
CREATE TABLE core.event_tombstones (
  event_id uuid PRIMARY KEY,
  source text NOT NULL,
  event_type text NOT NULL,
  ts_orig timestamptz,
  operation_id uuid NOT NULL,
  removed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE core.replayed_sequences (
  operation_id uuid NOT NULL,
  first_part uuid NOT NULL,
  completed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (operation_id, first_part)
);
CREATE TABLE core.commit_log (
  commit_seq bigint PRIMARY KEY,
  event_id uuid,
  event_type text,
  persisted_at timestamptz DEFAULT now(),
  CHECK ((event_id IS NULL) = (event_type IS NULL))
);
CREATE TABLE core.counters (name text PRIMARY KEY, value bigint NOT NULL);
INSERT INTO core.counters (name, value) VALUES ('commit_seq', 0);
CREATE TABLE core.source_counts (
  source text PRIMARY KEY,
  events bigint NOT NULL CHECK (events >= 0),
  first_event timestamptz,
  last_event timestamptz,
  last_seen timestamptz NOT NULL
);
CREATE TABLE core.excised_materials (
  material_id uuid PRIMARY KEY,
  blob text NOT NULL,
  operation_id uuid NOT NULL
);
CREATE INDEX excised_materials_blob ON core.excised_materials (blob);
CREATE TABLE core.consumer_positions (
  consumer text PRIMARY KEY,
  commit_seq bigint NOT NULL,
  change_seq bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE core.published (
  event_id uuid PRIMARY KEY,
  stream_seq bigint NOT NULL
);
CREATE TABLE core.ingress_frames (
  number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
  producer text NOT NULL,
  frame text NOT NULL,
  material_id uuid,
  admitted uuid[] NOT NULL DEFAULT '{}',
  outcome jsonb NOT NULL,
  refusal text,
  commit_seq bigint,
  received_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (producer, frame)
);
CREATE TABLE audit.archived (
  event_id uuid PRIMARY KEY,
  change_seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
  archived_seq bigint NOT NULL,
  reason text NOT NULL CHECK (reason IN ('replay', 'newer_reading', 'hide', 'recomputed')),
  replaced_by uuid,
  operation_id uuid,
  archived_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE audit.archive_changes (
  change_seq bigint PRIMARY KEY,
  event_id uuid NOT NULL,
  commit_seq bigint NOT NULL,
  archived boolean NOT NULL,
  reason text NOT NULL CHECK (reason IN ('replay', 'newer_reading', 'hide', 'recomputed', 'unhide')),
  replaced_by uuid,
  operation_id uuid,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, commit_seq),
  CHECK (archived = (reason <> 'unhide'))
);
CREATE INDEX archive_changes_position ON audit.archive_changes (event_id, commit_seq DESC);
CREATE TABLE core.blobs (
  hash text PRIMARY KEY CHECK (hash ~ '^blake3:[0-9a-f]{64}$'),
  size bigint NOT NULL CHECK (size >= 0),
  -- The file is written before the admission that inserts this row.
  -- `deleting`: an excision left the bytes unreferenced; the writer deletes
  -- the file under this row's lock, then the row, after commit or when the
  -- daemon starts. The writer admits no row whose file is missing.
  status text NOT NULL CHECK (status IN ('present', 'deleting')),
  registered_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE core.event_blobs (
  event_id uuid NOT NULL,
  blob text NOT NULL REFERENCES core.blobs(hash),
  PRIMARY KEY (event_id, blob)
);
CREATE INDEX event_blobs_blob ON core.event_blobs (blob);
CREATE TABLE raw.inputs (
  id uuid PRIMARY KEY,
  binding text NOT NULL,
  kind text NOT NULL,
  locator text NOT NULL,
  host text NOT NULL,
  UNIQUE (binding, locator, host)
);
CREATE TABLE raw.observations (
  id uuid PRIMARY KEY,
  input_id uuid NOT NULL REFERENCES raw.inputs(id),
  observed_at timestamptz NOT NULL,
  size numeric,
  mtime_ns numeric,
  ctime_ns numeric,
  inode numeric,
  device numeric,
  unavailable text,
  unchanged_looks bigint NOT NULL DEFAULT 0,
  last_looked_at timestamptz NOT NULL
);
CREATE INDEX observations_input ON raw.observations (input_id, observed_at);
CREATE TABLE raw.revisions (
  id uuid PRIMARY KEY,
  input_id uuid NOT NULL REFERENCES raw.inputs(id),
  previous_id uuid REFERENCES raw.revisions(id),
  kind text NOT NULL CHECK (kind IN ('appended', 'rewritten', 'replaced', 'truncated', 'snapshot')),
  started_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE raw.materials (
  id uuid PRIMARY KEY,
  input_id uuid REFERENCES raw.inputs(id),
  revision_id uuid REFERENCES raw.revisions(id),
  part_index integer NOT NULL DEFAULT 0,
  previous_part_id uuid REFERENCES raw.materials(id),
  blob text NOT NULL REFERENCES core.blobs(hash),
  length bigint NOT NULL CHECK (length >= 0),
  manifest jsonb NOT NULL,
  parser text NOT NULL,
  parser_version integer NOT NULL
);
CREATE INDEX materials_input ON raw.materials (input_id, part_index);
CREATE TABLE raw.failures (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  material_id uuid NOT NULL REFERENCES raw.materials(id),
  anchor bigint NOT NULL,
  reason text NOT NULL,
  run_id uuid NOT NULL,
  failed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE raw.bindings (
  binding text PRIMARY KEY,
  source text NOT NULL,
  input text NOT NULL,
  settings jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE raw.positions (
  binding text PRIMARY KEY,
  cursor jsonb NOT NULL,
  carry jsonb NOT NULL,
  committed_seq bigint NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE raw.reader_memory (
  binding text PRIMARY KEY,
  material_id uuid NOT NULL REFERENCES raw.materials(id),
  memory bytea NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE core.manifests (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('source', 'derivation', 'producer', 'capture_node', 'api')),
  version text NOT NULL,
  build text NOT NULL,
  emits text[] NOT NULL DEFAULT '{}',
  reads text[] NOT NULL DEFAULT '{}',
  UNIQUE (name, version, build)
);
CREATE TABLE core.runs (
  id uuid PRIMARY KEY,
  manifest_id uuid REFERENCES core.manifests(id),
  name text NOT NULL,
  host text NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz,
  -- The newest privacy rule row in force when the run's events were admitted.
  privacy_rules_seq bigint,
  -- How many of the run's events are stored, kept by admission and
  -- excision.
  events bigint NOT NULL DEFAULT 0
);
CREATE TABLE core.operations (
  id uuid PRIMARY KEY,
  kind text NOT NULL,
  actor text NOT NULL,
  scope jsonb NOT NULL,
  at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE registry.event_types (
  name text PRIMARY KEY,
  payload_schema jsonb NOT NULL,
  key_kind text NOT NULL CHECK (key_kind IN ('location', 'fields')),
  key_fields text[] NOT NULL,
  replace_rule text NOT NULL CHECK (replace_rule IN ('replace_when_newer', 'suppress_repeat'))
);
CREATE TABLE registry.sources (
  name text PRIMARY KEY,
  driver text NOT NULL,
  version integer NOT NULL,
  event_types text[] NOT NULL,
  purpose text NOT NULL
);
CREATE TABLE registry.derivations (
  name text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('per_event', 'keyed')),
  version integer NOT NULL,
  inputs text[] NOT NULL,
  outputs text[] NOT NULL
);
CREATE TABLE derivation.dirty (
  derivation text NOT NULL,
  key jsonb NOT NULL,
  first_dirty_seq bigint NOT NULL,
  last_dirty_seq bigint NOT NULL,
  PRIMARY KEY (derivation, key)
);
CREATE TABLE derivation.positions (derivation text PRIMARY KEY, commit_seq bigint NOT NULL);
CREATE TABLE derivation.outputs (
  derivation text NOT NULL,
  key jsonb NOT NULL,
  event_id uuid NOT NULL,
  PRIMARY KEY (derivation, key, event_id)
);
CREATE INDEX outputs_event ON derivation.outputs (event_id);
CREATE TABLE derivation.waiting (
  derivation text NOT NULL,
  key jsonb NOT NULL,
  since timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (derivation, key)
);
CREATE TABLE derivation.comparisons (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  derivation text NOT NULL,
  version integer NOT NULL,
  range_from timestamptz,
  range_until timestamptz,
  made_at timestamptz NOT NULL DEFAULT now(),
  keys bigint NOT NULL,
  unchanged bigint NOT NULL,
  added bigint NOT NULL,
  changed bigint NOT NULL,
  removed bigint NOT NULL,
  examples jsonb NOT NULL
);
CREATE TABLE privacy.rules (
  seq bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  id uuid NOT NULL UNIQUE,
  name text NOT NULL,
  source text NOT NULL,
  event_type text,
  field text CHECK (field IS NULL OR field LIKE '/%'),
  matcher text NOT NULL CHECK (matcher IN ('all', 'pattern', 'terms', 'luhn', 'iban')),
  matcher_arg text,
  class text NOT NULL CHECK (class IN ('open', 'guarded', 'sealed')),
  action text NOT NULL CHECK (action IN ('classify', 'mask', 'hash', 'drop_field')),
  author text NOT NULL,
  written_at timestamptz NOT NULL DEFAULT now(),
  ended boolean NOT NULL DEFAULT false
);
CREATE INDEX rules_name ON privacy.rules (name, seq DESC);
CREATE TABLE privacy.source_classes (
  seq bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source text NOT NULL,
  class text NOT NULL CHECK (class IN ('open', 'guarded', 'sealed')),
  author text NOT NULL,
  written_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE privacy.settings (
  id boolean PRIMARY KEY CHECK (id),
  hash_key bytea NOT NULL CHECK (length(hash_key) = 32)
);
CREATE TABLE privacy.data_keys (
  material_id uuid PRIMARY KEY,
  key_ref text NOT NULL UNIQUE,
  class text NOT NULL,
  wrapped_key bytea NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE core.search_text (
  event_id uuid PRIMARY KEY,
  text text NOT NULL,
  tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple', text)) STORED
);
CREATE INDEX search_text_tsv ON core.search_text USING gin (tsv);
CREATE INDEX search_text_trigram ON core.search_text USING gin (text gin_trgm_ops);
CREATE UNLOGGED TABLE core.admission_stage (
  ord integer PRIMARY KEY,
  id uuid NOT NULL,
  event_type text NOT NULL,
  source text NOT NULL,
  material_id uuid,
  anchor bigint,
  output_index smallint NOT NULL,
  parents uuid[],
  ts_orig timestamptz,
  ts_quality text NOT NULL,
  payload jsonb NOT NULL,
  equivalence_key text,
  replace_rule text NOT NULL,
  reading_order bigint NOT NULL,
  record_hash bytea NOT NULL,
  record_state text NOT NULL,
  class text NOT NULL
);
CREATE FUNCTION audit.is_archived_at(target_event uuid, at_seq bigint) RETURNS boolean LANGUAGE SQL STABLE PARALLEL SAFE AS $$
SELECT coalesce((SELECT archived FROM audit.archive_changes
  WHERE event_id = target_event AND commit_seq <= at_seq ORDER BY commit_seq DESC LIMIT 1), false)
$$;
CREATE OR REPLACE FUNCTION core.event_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'event rows are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' AND nullif(current_setting('sinex.excise_operation', true), '') IS NULL THEN
    RAISE EXCEPTION 'events are deleted only by an excision' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END $$;
SELECT create_hypertable('core.events', by_range('id', INTERVAL '1 day'), create_default_indexes => false);
CREATE INDEX ON core.events (ts_orig);
CREATE INDEX ON core.events (source, ts_orig);
CREATE INDEX ON core.events (event_type, ts_orig);
CREATE INDEX ON core.events (material_id, anchor);
CREATE INDEX ON core.events USING gin (parents) WITH (fastupdate = off) WHERE parents IS NOT NULL;
CREATE TRIGGER event_guard BEFORE UPDATE OR DELETE ON core.events FOR EACH ROW EXECUTE FUNCTION core.event_guard();
ALTER TABLE core.events SET (timescaledb.compress, timescaledb.compress_segmentby = 'source, event_type', timescaledb.compress_orderby = 'ts_orig, id');
SELECT enable_chunk_skipping('core.events', 'ts_orig');
SELECT add_compression_policy('core.events', INTERVAL '7 days');
SELECT create_hypertable('telemetry.events', by_range('id', INTERVAL '1 day'), create_default_indexes => false);
CREATE INDEX ON telemetry.events (ts_orig);
CREATE INDEX ON telemetry.events (source, ts_orig);
CREATE INDEX ON telemetry.events (event_type, ts_orig);
CREATE INDEX ON telemetry.events (material_id, anchor);
CREATE INDEX ON telemetry.events USING gin (parents) WITH (fastupdate = off) WHERE parents IS NOT NULL;
CREATE TRIGGER event_guard BEFORE UPDATE OR DELETE ON telemetry.events FOR EACH ROW EXECUTE FUNCTION core.event_guard();
ALTER TABLE telemetry.events SET (timescaledb.compress, timescaledb.compress_segmentby = 'source, event_type', timescaledb.compress_orderby = 'ts_orig, id');
SELECT enable_chunk_skipping('telemetry.events', 'ts_orig');
SELECT add_compression_policy('telemetry.events', INTERVAL '7 days');
CREATE FUNCTION core.class_visible(class text) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT class = 'open'
      OR class = ANY (string_to_array(coalesce(current_setting('sinex.grants', true), ''), ','))
$$;
CREATE VIEW core.visible_events AS SELECT
  e.id, e.event_type, e.source, e.run_id, e.material_id, e.anchor, e.output_index, e.parents,
  e.ts_orig, e.ts_quality, e.ts_coided, e.ts_persisted, e.commit_seq,
  CASE WHEN core.class_visible(e.class) THEN e.payload
       ELSE jsonb_build_object('withheld', e.class) END AS payload,
  CASE WHEN core.class_visible(e.class) THEN e.equivalence_key END AS equivalence_key,
  e.reading_order, e.record_hash, e.record_state, e.class
FROM core.events e;
CREATE VIEW core.visible_search_text AS SELECT s.event_id, s.text, s.tsv
FROM core.search_text s JOIN core.events e ON e.id = s.event_id
WHERE core.class_visible(e.class);
CREATE VIEW event_types."forecast_issued" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'forecast' AS "forecast", e.payload->'target' AS "target", e.payload->'criteria' AS "criteria", e.payload->'probability' AS "probability", e.payload->'horizon' AS "horizon", e.payload->'information_cutoff' AS "information_cutoff", e.payload->'information' AS "information", e.payload->'information_position' AS "information_position", e.payload->'by' AS "by", e.payload->'at' AS "at" FROM core.visible_events e WHERE e.event_type='forecast.issued' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."forecast_resolved" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'forecast' AS "forecast", e.payload->'outcome' AS "outcome", e.payload->'outcome_at' AS "outcome_at", e.payload->'evidence' AS "evidence", e.payload->'by' AS "by", e.payload->'at' AS "at" FROM core.visible_events e WHERE e.event_type='forecast.resolved' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."command_executed" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'native_id' AS "native_id", e.payload->'command' AS "command", e.payload->'cwd' AS "cwd", e.payload->'session' AS "session", e.payload->'hostname' AS "hostname", e.payload->'started_at' AS "started_at", e.payload->'duration_ns' AS "duration_ns", e.payload->'exit_code' AS "exit_code", e.payload->'deleted_at' AS "deleted_at", e.payload->'author' AS "author", e.payload->'intent' AS "intent", e.payload->'shell' AS "shell", e.payload->'extra' AS "extra" FROM core.visible_events e WHERE e.event_type='command.executed' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."command_imported" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'command' AS "command", e.payload->'hostname' AS "hostname", e.payload->'started_at' AS "started_at", e.payload->'header_elapsed' AS "header_elapsed", e.payload->'paths' AS "paths", e.payload->'n' AS "n" FROM core.visible_events e WHERE e.event_type='command.imported' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."window_focused" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'received_at' AS "received_at", e.payload->'window' AS "window", e.payload->'class' AS "class", e.payload->'title' AS "title" FROM core.visible_events e WHERE e.event_type='window.focused' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."window_opened" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'received_at' AS "received_at", e.payload->'window' AS "window", e.payload->'workspace_id' AS "workspace_id", e.payload->'workspace_name' AS "workspace_name", e.payload->'class' AS "class", e.payload->'title' AS "title" FROM core.visible_events e WHERE e.event_type='window.opened' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."window_closed" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'received_at' AS "received_at", e.payload->'window' AS "window" FROM core.visible_events e WHERE e.event_type='window.closed' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."window_moved" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'received_at' AS "received_at", e.payload->'window' AS "window", e.payload->'workspace_id' AS "workspace_id", e.payload->'workspace_name' AS "workspace_name" FROM core.visible_events e WHERE e.event_type='window.moved' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."window_title_changed" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'received_at' AS "received_at", e.payload->'window' AS "window", e.payload->'title' AS "title" FROM core.visible_events e WHERE e.event_type='window.title_changed' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
