CREATE VIEW event_types."account_setting" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'service' AS "service", e.payload->'setting' AS "setting", e.payload->'value' AS "value", e.payload->'extra' AS "extra" FROM core.visible_events e WHERE e.event_type='account.setting' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."operator_log_entry" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'written_at' AS "written_at", e.payload->'label' AS "label", e.payload->'text' AS "text" FROM core.visible_events e WHERE e.event_type='operator_log.entry' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."steering_row" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'table' AS "table", e.payload->'record_id' AS "record_id", e.payload->'at' AS "at", e.payload->'values' AS "values" FROM core.visible_events e WHERE e.event_type='steering.row' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_copy" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'host' AS "host", e.payload->'root' AS "root", e.payload->'path' AS "path", e.payload->'content' AS "content", e.payload->'size' AS "size", e.payload->'sha256' AS "sha256", e.payload->'md5' AS "md5", e.payload->'media_type' AS "media_type", e.payload->'width' AS "width", e.payload->'height' AS "height", e.payload->'duration_ms' AS "duration_ms", e.payload->'stored' AS "stored", e.payload->'device' AS "device", e.payload->'inode' AS "inode", e.payload->'modified_at' AS "modified_at", e.payload->'moved_from' AS "moved_from", e.payload->'previous_content' AS "previous_content", e.payload->'vanished_at' AS "vanished_at" FROM core.visible_events e WHERE e.event_type='library.copy' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_item" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'item' AS "item", e.payload->'revision' AS "revision", e.payload->'replaces' AS "replaces", e.payload->'content' AS "content", e.payload->'media_type' AS "media_type", e.payload->'copies' AS "copies", e.payload->'label' AS "label", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.item' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_rendition" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'rendition' AS "rendition", e.payload->'item' AS "item", e.payload->'revision' AS "revision", e.payload->'role' AS "role", e.payload->'content' AS "content", e.payload->'media_type' AS "media_type", e.payload->'width' AS "width", e.payload->'height' AS "height", e.payload->'duration_ms' AS "duration_ms", e.payload->'made_from' AS "made_from", e.payload->'made_with' AS "made_with", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.rendition' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_assignment" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'assignment' AS "assignment", e.payload->'target' AS "target", e.payload->'field' AS "field", e.payload->'value' AS "value", e.payload->'level' AS "level", e.payload->'source_ref' AS "source_ref", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.assignment' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_collection" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'collection' AS "collection", e.payload->'name' AS "name", e.payload->'saved_query' AS "saved_query", e.payload->'selected_from' AS "selected_from", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.collection' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_entry" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'entry' AS "entry", e.payload->'collection' AS "collection", e.payload->'target' AS "target", e.payload->'position' AS "position", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.entry' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_rating" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'item' AS "item", e.payload->'scale' AS "scale", e.payload->'value' AS "value", e.payload->'of' AS "of", e.payload->'level' AS "level", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.rating' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_comparison" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'comparison' AS "comparison", e.payload->'scale' AS "scale", e.payload->'winner' AS "winner", e.payload->'loser' AS "loser", e.payload->'by' AS "by", e.payload->'at' AS "at", e.payload->'withdrawn_at' AS "withdrawn_at" FROM core.visible_events e WHERE e.event_type='library.comparison' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_view" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'view' AS "view", e.payload->'target' AS "target", e.payload->'player' AS "player", e.payload->'started_at' AS "started_at", e.payload->'seconds' AS "seconds", e.payload->'count' AS "count", e.payload->'level' AS "level", e.payload->'by' AS "by" FROM core.visible_events e WHERE e.event_type='library.view' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
CREATE VIEW event_types."library_dismissal" AS SELECT e.id, e.source, e.ts_orig, e.ts_quality, e.ts_coided, e.record_state, e.payload->'collection' AS "collection", e.payload->'item' AS "item", e.payload->'query' AS "query", e.payload->'by' AS "by", e.payload->'at' AS "at" FROM core.visible_events e WHERE e.event_type='library.dismissal' AND NOT EXISTS (SELECT 1 FROM audit.archived a WHERE a.event_id=e.id);
