INSERT INTO sinex_schema.applied(version) VALUES (2);
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('forecast.issued','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Issued","type":"object","properties":{"forecast":{"type":"string"},"target":{"type":"string"},"criteria":{"type":"string"},"probability":{"type":"number","format":"double"},"horizon":{"$ref":"#/$defs/Timestamp"},"information_cutoff":{"$ref":"#/$defs/Timestamp"},"information":{"description":"Visible event IDs available when the forecast was issued.","type":"array","items":{"type":"string"}},"information_position":{"type":"integer","format":"int64"},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"}},"additionalProperties":false,"required":["forecast","target","criteria","probability","horizon","information_cutoff","information","information_position","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['forecast']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('forecast.resolved','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Resolved","type":"object","properties":{"forecast":{"type":"string"},"outcome":{"description":"An unknown outcome is recorded explicitly and is never scored as false.","type":["boolean","null"]},"outcome_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"evidence":{"type":"array","items":{"type":"string"}},"by":{"type":"string"},"at":{"description":"When this resolution was recorded, distinct from the outcome''s time.","$ref":"#/$defs/Timestamp"}},"additionalProperties":false,"required":["forecast","evidence","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('command.executed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"CommandExecuted","description":"A command run in a shell, as Atuin recorded it. Atuin updates rows in place\n(duration and exit arrive when the command ends; `deleted_at` when the\noperator deletes it), so a newer reading with different content replaces\nthe live one.","type":"object","properties":{"native_id":{"description":"Atuin''s own row ID.","type":"string"},"command":{"type":"string"},"cwd":{"type":"string"},"session":{"type":"string"},"hostname":{"type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"duration_ns":{"description":"`None` while the command is still running (Atuin stores -1).","type":["integer","null"],"format":"int64"},"exit_code":{"description":"`None` while the command is still running. Exit codes are signed: a\nsignal-killed command is negative.","type":["integer","null"],"format":"int64"},"deleted_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"author":{"type":["string","null"]},"intent":{"type":["string","null"]},"shell":{"type":["string","null"]},"extra":{"description":"Columns this parser does not know yet, kept by name.","type":"object","additionalProperties":true}},"required":["native_id","command","cwd","session","hostname","started_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('command.imported','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"CommandImported","description":"A command from a shell''s history file: zsh (plain or extended), bash\n(with or without `#` timestamp lines) or fish. The source names the shell.\nTimed records keep their equivalence key across materials; untimed records use\ntheir material location because neither text nor an unknown start\nidentifies a record.","type":"object","properties":{"command":{"type":"string"},"hostname":{"type":"string"},"started_at":{"description":"Absent in plain history; acquisition time is not a command start.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"header_elapsed":{"description":"zsh''s elapsed seconds field as written. With SHARE_HISTORY zsh writes 0\nbefore the command ends, so this is not a duration.","type":["integer","null"],"format":"int64"},"paths":{"description":"The arguments fish recorded as existing paths, in its order.","type":"array","items":{"type":"string"}},"n":{"description":"Which record this is among records with the same start second and\ncommand, in file order (the same command run twice in one second is\ntwo runs). Untimed records use their material location instead; this\ndiscriminator is zero and unused for them.\nWith host, start and command it identifies the timed record\nwherever it is read from, so a re-read from the start (a lost position,\nbytes stored again) is a repeat, not a new command.","type":"integer","format":"uint32","minimum":0}},"required":["command","hostname","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['hostname','started_at','command','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.focused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowFocused","description":"A window took keyboard focus.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"window":{"description":"The compositor''s window address; `None` when only class and title were\nreported before the next event arrived.","type":["string","null"]},"class":{"type":["string","null"]},"title":{"type":["string","null"]}},"required":["received_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.opened','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowOpened","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"window":{"type":"string"},"workspace_id":{"type":["integer","null"],"format":"int64"},"workspace_name":{"type":"string"},"class":{"type":"string"},"title":{"type":"string"}},"required":["received_at","window","workspace_name","class","title"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.closed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowClosed","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"window":{"type":"string"}},"required":["received_at","window"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.moved','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowMoved","description":"A window moved to another workspace.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"window":{"type":"string"},"workspace_id":{"type":["integer","null"],"format":"int64"},"workspace_name":{"type":"string"}},"required":["received_at","window","workspace_name"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.title_changed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowTitleChanged","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"window":{"type":"string"},"title":{"type":"string"}},"required":["received_at","window","title"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('workspace.switched','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WorkspaceSwitched","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"workspace_id":{"type":["integer","null"],"format":"int64"},"workspace_name":{"type":["string","null"]}},"required":["received_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('monitor.focused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MonitorFocused","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"monitor":{"type":"string"},"workspace_name":{"type":"string"}},"required":["received_at","monitor","workspace_name"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('desktop.other','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"DesktopOther","description":"A compositor event Sinex has no type for yet, kept whole.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"name":{"type":"string"},"data":{"type":"string"}},"required":["received_at","name","data"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('notification.shown','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NotificationShown","description":"A desktop notification was asked for (`org.freedesktop.Notifications.Notify`).","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"app":{"description":"The application name the sender gave.","type":"string"},"summary":{"type":"string"},"body":{"type":"string"},"icon":{"type":["string","null"]},"replaces_id":{"description":"The notification this one replaces, when the sender gave one.","type":["integer","null"],"format":"uint32","minimum":0},"actions":{"description":"Action identifiers and labels, in the order sent.","type":"array","items":{"type":"string"}},"hints":{"description":"Hints the sender attached (urgency, category, desktop entry…), as sent.","type":"object","additionalProperties":true},"expire_timeout_ms":{"description":"How long the sender asked it to stay, in milliseconds (`-1`: the\nserver decides, `0`: until dismissed).","type":"integer","format":"int32"},"sender":{"description":"The sender''s unique bus name.","type":"string"}},"required":["received_at","app","summary","body","actions","expire_timeout_ms","sender"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('notification.closed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NotificationClosed","description":"A notification closed (`NotificationClosed`).","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"notification_id":{"type":"integer","format":"uint32","minimum":0},"reason":{"description":"`expired`, `dismissed`, `closed` (by the sender) or `undefined`.","type":"string"}},"required":["received_at","notification_id","reason"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('notification.action','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NotificationAction","description":"The operator picked one of a notification''s actions (`ActionInvoked`).","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"notification_id":{"type":"integer","format":"uint32","minimum":0},"action":{"type":"string"}},"required":["received_at","notification_id","action"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('clipboard.copied','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ClipboardCopied","description":"The clipboard or the primary selection changed.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"selection":{"description":"`clipboard` or `primary`.","type":"string"},"mime_types":{"description":"The types the owner offered, in its order.","type":"array","items":{"type":"string"}},"mime_type":{"description":"The type whose content was read.","type":["string","null"]},"text":{"description":"The content when it is text; binary content stays in the stored bytes.","type":["string","null"]},"bytes":{"type":"integer","format":"uint64","minimum":0},"content_hash":{"description":"BLAKE3 of the content, so a repeated copy can be recognized.","type":["string","null"]},"secret":{"description":"The owner marked it a secret (a password manager''s hint); its content\nwas not read.","type":"boolean"}},"required":["received_at","selection","mime_types","bytes","secret"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('player.changed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PlayerChanged","description":"A media player''s state changed (MPRIS `PropertiesChanged`), or was read\nwhen capture started.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"player":{"description":"The player''s well-known name (`org.mpris.MediaPlayer2.spotify`) when\nknown, else its unique bus name.","type":"string"},"status":{"description":"`Playing`, `Paused` or `Stopped`, when it changed.","type":["string","null"]},"title":{"type":["string","null"]},"artists":{"type":"array","items":{"type":"string"}},"album":{"type":["string","null"]},"url":{"type":["string","null"]},"length_us":{"type":["integer","null"],"format":"int64"},"snapshot":{"description":"`true` when this is the state read at capture start, not a change.","type":"boolean"},"properties":{"description":"Every changed property as sent, decoded from D-Bus types.","type":"object","additionalProperties":true}},"required":["received_at","player","artists","snapshot"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('editor.reported','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"EditorReport","description":"Something the editor reported (a Neovim autocommand).","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"editor":{"type":"string"},"event":{"description":"The autocommand (`BufEnter`, `BufWritePost`, `VimLeave`…).","type":"string"},"path":{"type":["string","null"]},"filetype":{"type":["string","null"]},"cwd":{"type":["string","null"]},"pid":{"type":["integer","null"],"format":"uint32","minimum":0},"extra":{"description":"Any other fields the editor sent.","type":"object","additionalProperties":true}},"required":["received_at","editor","event"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('terminal.reported','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"TerminalReport","description":"Something the terminal reported (a kitty watcher callback).","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"terminal":{"type":"string"},"event":{"description":"`cmd_start`, `cmd_end`, `focus`, `close`, `title`…","type":"string"},"window_id":{"type":["integer","null"],"format":"int64"},"cwd":{"type":["string","null"]},"cmdline":{"type":["string","null"]},"exit_status":{"type":["integer","null"],"format":"int64"},"title":{"type":["string","null"]},"output":{"description":"What the command printed, escape sequences removed (`cmd_end` with\nkitty''s shell integration).","type":["string","null"]},"extra":{"type":"object","additionalProperties":true}},"required":["received_at","terminal","event"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('media.segment','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MediaSegment","description":"A segment of screen or audio capture: the stored material is the segment\nitself (an image or an audio file).","type":"object","properties":{"kind":{"description":"`screen` or `audio`.","type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"mime":{"type":"string"},"bytes":{"type":"integer","format":"uint64","minimum":0},"target":{"description":"The output (monitor) or audio target captured.","type":["string","null"]},"width":{"type":["integer","null"],"format":"uint32","minimum":0},"height":{"type":["integer","null"],"format":"uint32","minimum":0}},"required":["kind","started_at","ended_at","mime","bytes"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('screen.text','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ScreenText","description":"Text read from a screen segment by a local OCR engine. Derived from the\nsegment''s event; recomputed when the engine version changes.","type":"object","properties":{"segment":{"description":"The `media.segment` event this text was read from.","type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"engine":{"type":"string"},"text":{"type":"string"}},"required":["segment","started_at","engine","text"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['segment']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('page.fetched','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PageFetched","description":"A page from browser history, fetched by the forward crawl. The stored\nmaterial is the response body; a later fetch of the same URL is a newer\nreading.","type":"object","properties":{"url":{"type":"string"},"final_url":{"type":"string"},"fetched_at":{"$ref":"#/$defs/Timestamp"},"status":{"type":"integer","format":"uint16","minimum":0,"maximum":65535},"content_type":{"type":["string","null"]},"bytes":{"type":"integer","format":"uint64","minimum":0},"title":{"type":["string","null"]}},"required":["url","final_url","fetched_at","status","bytes"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['url']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.span','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowSpan","description":"ActivityWatch''s window watcher: the focused application and title over a\nspan. ActivityWatch extends a span in place while the window stays the\nsame, and the source joins adjacent identical events, so a newer reading\nof the span replaces the older one.","type":"object","properties":{"bucket":{"type":"string"},"span_id":{"description":"The row ID of the first ActivityWatch event in this span.","type":"integer","format":"int64"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"app":{"type":"string"},"title":{"description":"The title with animation glyphs removed (see the ActivityWatch source).","type":"string"},"merged":{"description":"How many ActivityWatch events this span combines.","type":"integer","format":"uint32","minimum":0}},"required":["bucket","span_id","started_at","ended_at","app","title","merged"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['bucket','span_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('presence.span','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PresenceSpan","description":"ActivityWatch''s AFK watcher: whether the operator was at the machine.","type":"object","properties":{"bucket":{"type":"string"},"row":{"type":"integer","format":"int64"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"status":{"description":"`afk` or `not-afk`, as reported.","type":"string"}},"required":["bucket","row","started_at","ended_at","status"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['bucket','row']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('presence.interval','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PresenceInterval","description":"Whether the operator was at the machine over an interval, judged from\nActivityWatch''s AFK watcher and corroborating input. The watcher misses idle\ntransitions under load, so a long not-afk stretch with no input is\n`uncertain`, never silently `present`. Derived per logical day by the\npresence derivation; the reported spans stay as read.","type":"object","properties":{"day":{"description":"The logical day this interval was computed for (intervals are cut at\nday boundaries).","type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"state":{"description":"`present`, `absent` or `uncertain`.","type":"string"},"sparse":{"description":"Present, but with less input than the dense threshold: a real but\nquiet stretch (reading, a call), not an artifact.","type":"boolean"},"reported":{"description":"ActivityWatch''s status for the span (`afk`, `not-afk`).","type":"string"},"evidence":{"description":"Corroborating input events inside the interval.","type":"integer","format":"uint32","minimum":0}},"required":["day","started_at","ended_at","state","sparse","reported","evidence"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['day','started_at']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('browser.tab_active','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BrowserTabActive","description":"ActivityWatch''s browser watcher: the active tab over a span.","type":"object","properties":{"bucket":{"type":"string"},"row":{"type":"integer","format":"int64"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"browser":{"type":"string"},"url":{"type":"string"},"title":{"type":"string"},"incognito":{"type":["boolean","null"]},"audible":{"type":["boolean","null"]},"tab_count":{"type":["integer","null"],"format":"int64"}},"required":["bucket","row","started_at","ended_at","browser","url","title"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['bucket','row']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('activitywatch.other','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ActivityWatchOther","description":"An ActivityWatch event from a watcher Sinex has no type for yet, kept whole.","type":"object","properties":{"bucket":{"type":"string"},"row":{"type":"integer","format":"int64"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"data":true},"required":["bucket","row","started_at","ended_at","data"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['bucket','row']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('window.sampled','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"WindowSampled","description":"One sample of a window-sampling tracker (arbtt): every open window, which\none was active, and how long input had been idle, taken every `rate_ms`.\nThe sample''s place in the log is its identity.","type":"object","properties":{"sampled_at":{"$ref":"#/$defs/Timestamp"},"rate_ms":{"description":"The sampling interval the tracker recorded.","type":"integer","format":"int64"},"idle_ms":{"description":"Milliseconds since the last keyboard or mouse input.","type":"integer","format":"int64"},"active_title":{"description":"The active window''s title and program, when one was active.","type":["string","null"]},"active_program":{"type":["string","null"]},"desktop":{"type":["string","null"]},"windows":{"type":"array","items":{"$ref":"#/$defs/SampledWindow"}}},"required":["sampled_at","rate_ms","idle_ms","windows"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"SampledWindow":{"type":"object","properties":{"active":{"type":"boolean"},"title":{"type":"string"},"program":{"type":"string"}},"required":["active","title","program"]}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('journal.entry','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"JournalEntry","description":"One systemd journal entry. The journal''s own cursor identifies it, so an\nentry read again (after a capture restart overlaps, or from an export) is\na repeat.","type":"object","properties":{"cursor":{"description":"`__CURSOR`.","type":"string"},"logged_at":{"description":"`__REALTIME_TIMESTAMP`; `None` when the entry has none or it is malformed\n(the time stays unknown rather than becoming the read time).","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"boot_id":{"type":["string","null"]},"hostname":{"type":["string","null"]},"message":{"description":"`MESSAGE`; `None` when the journal stored it as binary, which is kept\nin `fields` as an array of bytes.","type":["string","null"]},"priority":{"description":"syslog priority, 0 (emergency) to 7 (debug).","type":["integer","null"],"format":"uint8","minimum":0,"maximum":255},"unit":{"type":["string","null"]},"user_unit":{"type":["string","null"]},"identifier":{"type":["string","null"]},"pid":{"type":["integer","null"],"format":"int64"},"uid":{"type":["integer","null"],"format":"int64"},"command":{"type":["string","null"]},"transport":{"type":["string","null"]},"fields":{"description":"Every other field, by its journal name.","type":"object","additionalProperties":true}},"required":["cursor"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['cursor']::text[],'suppress_repeat');
