INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('file.changed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"FileChanged","description":"A change to a watched file or directory, as the kernel reported it.","type":"object","properties":{"received_at":{"$ref":"#/$defs/Timestamp"},"change":{"description":"`created`, `modified`, `written` (closed after writing), `removed`,\n`renamed`, `moved_from`, `moved_to`, `attributes`, `other`, or\n`unwatched` (the kernel refused a watch on this directory; see `note`).","type":"string"},"path":{"description":"The path, when it is UTF-8 (otherwise see `path_hex`).","type":["string","null"]},"path_hex":{"description":"The path''s bytes in hex, when they are not UTF-8.","type":["string","null"]},"to":{"description":"The new path, for a rename that reported both ends.","type":["string","null"]},"is_dir":{"type":["boolean","null"]},"note":{"description":"Why, for an `unwatched` directory.","type":["string","null"]}},"required":["received_at","change"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('terminal.session','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"TerminalSession","description":"A terminal recording''s session (asciinema): its start, size, command and\nenvironment, from the recording''s header. The recording''s place is its\nidentity.","type":"object","properties":{"session":{"type":"string"},"started_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"cols":{"type":["integer","null"],"format":"int64"},"rows":{"type":["integer","null"],"format":"int64"},"command":{"type":["string","null"]},"header":{"description":"The header as recorded (terminal type, theme, environment)."}},"required":["session","header"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('terminal.output','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"TerminalOutput","description":"A span of a terminal recording, as plain text with escape sequences\nremoved: one shell command''s output where the recording kept input. A span\nstarts at a typed Enter, so it holds the command''s output, the next prompt\nand the next command line as typed up to its own Enter; it also ends at a\nsize bound, a resize or the exit. The cast stays whole as the material,\nand the span''s record is its exact byte range there, so the original\nstream is replayable from the material; per-event detail is a read over\nit.","type":"object","properties":{"session":{"type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"events":{"description":"Cast events in the span.","type":"integer","format":"uint32","minimum":0},"output":{"description":"What was written to the terminal (`o` events), escape sequences\nremoved.","type":"string"},"input":{"description":"What was typed (`i` events), when the recording kept input.","type":"string"},"resize":{"description":"The last resize (`r`) or the exit status (`x`) the span ends with.","type":["string","null"]},"exit":{"type":["string","null"]}},"required":["session","started_at","ended_at","events","output","input"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('scrollback.captured','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ScrollbackCaptured","description":"What a kitty window''s scrollback held when it was captured: a snapshot in\nthe Sinnix lake (`kitty @ get-text`, every window on a timer), or the kitty\nintegration''s capture of a window''s new lines on a cadence and when it\ncloses. `text` holds only the lines new since the previous capture of the\nsame window, escape sequences removed; the stored material keeps the\ncapture as taken.","type":"object","properties":{"captured_at":{"$ref":"#/$defs/Timestamp"},"host":{"type":["string","null"]},"kitty_pid":{"description":"The kitty process; absent in older lake snapshots.","type":["integer","null"],"format":"uint32","minimum":0},"window_id":{"type":"integer","format":"int64"},"title":{"description":"The window''s title; for a lake snapshot, as its file name spells it\n(the sidecar''s `scrollback.window` has it exactly).","type":["string","null"]},"cwd":{"type":["string","null"]},"lines":{"description":"Lines the window held at capture, scrollback and screen.","type":"integer","format":"uint64","minimum":0},"continues":{"description":"Whether `text` continues the previous capture of this window. False for\na window''s first capture, and when the previous capture is not where\nthis one starts (the window was cleared, or resized and its lines\nwrapped again): `text` is then the whole capture.","type":"boolean"},"new_lines":{"description":"Lines in `text`.","type":"integer","format":"uint64","minimum":0},"text":{"type":"string"}},"required":["captured_at","window_id","lines","continues","new_lines","text"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('scrollback.window','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ScrollbackWindow","description":"The window a lake scrollback snapshot was taken of, from the snapshot''s\nsidecar file: kitty''s title and working directory at capture.","type":"object","properties":{"captured_at":{"$ref":"#/$defs/Timestamp"},"host":{"type":["string","null"]},"kitty_pid":{"type":["integer","null"],"format":"uint32","minimum":0},"window_id":{"type":"integer","format":"int64"},"title":{"type":["string","null"]},"cwd":{"type":["string","null"]},"snapshot":{"description":"The snapshot''s file name.","type":"string"},"extra":{"description":"Any other fields the sidecar has.","type":"object","additionalProperties":true}},"required":["captured_at","window_id","snapshot"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('key.pressed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"KeyPressed","description":"A key went down, or repeated while held.","type":"object","properties":{"session":{"description":"The logger process that wrote the record, one per input device.","type":"string"},"logged_at":{"description":"When the logger wrote the record (milliseconds).","$ref":"#/$defs/Timestamp"},"kernel_at":{"description":"The kernel''s time of the key event (microseconds): the keystroke''s own\ntiming. Older logs do not have it. The logger''s time can trail it by\nseconds when the pipeline backs up.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"key":{"description":"The key''s name as the logger wrote it (`KEY_A`, or `KEY_106` when it\nhad no name for the code).","type":"string"},"code":{"description":"The kernel''s key code; absent in older logs.","type":["integer","null"],"format":"uint16","minimum":0,"maximum":65535},"value":{"description":"The kernel''s value: 1 pressed, 2 repeated while held; absent in older\nlogs, which logged presses only.","type":["integer","null"],"format":"int32"},"changed":{"description":"Whether the key changed the logger''s typed-text buffer.","type":["boolean","null"]},"clipboard":{"description":"The clipboard text the logger read when the key was a paste.","type":["string","null"]},"window":{"description":"The focused window, as older logs recorded it.","type":["string","null"]},"n":{"type":"integer","format":"uint32","minimum":0},"extra":{"description":"Fields this parser does not know yet, kept by name.","type":"object","additionalProperties":true}},"required":["session","logged_at","key","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','kernel_at','key','value','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('key.released','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"KeyReleased","description":"A key went up.","type":"object","properties":{"session":{"type":"string"},"logged_at":{"$ref":"#/$defs/Timestamp"},"kernel_at":{"description":"The kernel''s time of the key event; see [`KeyPressed::kernel_at`].","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"key":{"type":"string"},"code":{"type":["integer","null"],"format":"uint16","minimum":0,"maximum":65535},"value":{"type":["integer","null"],"format":"int32"},"changed":{"type":["boolean","null"]},"n":{"type":"integer","format":"uint32","minimum":0},"extra":{"type":"object","additionalProperties":true}},"required":["session","logged_at","key","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','kernel_at','key','value','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('pointer.button','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PointerButton","description":"A pointer button went down or up. The logger records no kernel time for\npointer records, so the time is the logger''s.","type":"object","properties":{"session":{"type":"string"},"logged_at":{"$ref":"#/$defs/Timestamp"},"button":{"description":"`BTN_LEFT`, `BTN_RIGHT`, `BTN_SIDE`…","type":"string"},"pressed":{"type":"boolean"},"value":{"description":"The kernel''s value as logged (1 down, 0 up).","type":"integer","format":"int64"},"n":{"type":"integer","format":"uint32","minimum":0},"extra":{"type":"object","additionalProperties":true}},"required":["session","logged_at","button","pressed","value","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','button','pressed','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('pointer.moved','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PointerMoved","description":"The pointer moved along one axis: a relative step (`REL_X`, `REL_Y`) or an\nabsolute position (`ABS_X`, a tablet''s).","type":"object","properties":{"session":{"type":"string"},"logged_at":{"$ref":"#/$defs/Timestamp"},"axis":{"type":"string"},"value":{"description":"The step (relative axes) or the position (absolute axes).","type":"integer","format":"int64"},"absolute":{"type":"boolean"},"n":{"type":"integer","format":"uint32","minimum":0},"extra":{"type":"object","additionalProperties":true}},"required":["session","logged_at","axis","value","absolute","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','axis','value','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('pointer.scrolled','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PointerScrolled","description":"A scroll wheel turned: `REL_WHEEL` and `REL_HWHEEL` in detents,\n`REL_WHEEL_HI_RES` and `REL_HWHEEL_HI_RES` in 1/120 of one.","type":"object","properties":{"session":{"type":"string"},"logged_at":{"$ref":"#/$defs/Timestamp"},"axis":{"type":"string"},"value":{"type":"integer","format":"int64"},"n":{"type":"integer","format":"uint32","minimum":0},"extra":{"type":"object","additionalProperties":true}},"required":["session","logged_at","axis","value","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','axis','value','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('input.logger','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"InputLogger","description":"A record about the logger itself (`start`, `stop`, a `focus` change in\nolder logs, a typed-text `snapshot`), or one of a kind this parser has no\ntype for, with its fields as written.","type":"object","properties":{"session":{"type":"string"},"logged_at":{"$ref":"#/$defs/Timestamp"},"event":{"description":"The record''s `event` as written.","type":"string"},"n":{"type":"integer","format":"uint32","minimum":0},"fields":{"type":"object","additionalProperties":true}},"required":["session","logged_at","event","n"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['session','logged_at','event','n']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('git.commit','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"GitCommit","description":"One commit. A commit never changes once made; its ID is its identity, so\nseeing it again (another ref, another clone at the same path) is a repeat.","type":"object","properties":{"repository":{"description":"The repository''s working directory (or git directory, when bare).","type":"string"},"commit":{"type":"string"},"parents":{"type":"array","items":{"type":"string"}},"tree":{"type":"string"},"author_name":{"type":"string"},"author_email":{"type":"string"},"authored_at":{"$ref":"#/$defs/Timestamp"},"committer_name":{"type":"string"},"committer_email":{"type":"string"},"committed_at":{"$ref":"#/$defs/Timestamp"},"message":{"description":"The full message, decoded lossily when it is not UTF-8.","type":"string"},"refs":{"description":"The refs that pointed at this commit when it was first read.","type":"array","items":{"type":"string"}}},"required":["repository","commit","parents","tree","author_name","author_email","authored_at","committer_name","committer_email","committed_at","message","refs"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['repository','commit']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('command.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"CommandFused","description":"One command run, from Atuin and zsh history. zsh history holds about a\nthousand pairs of the same command in the same second on the operator''s\nmachine, which is why the record, not the text and time, identifies it.","type":"object","properties":{"record":{"description":"The preferred member''s identity: `<type>:<native id>` when the source\nhas one (Atuin), otherwise its record location.","type":"string"},"command":{"type":"string"},"host":{"type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"cwd":{"type":["string","null"]},"session":{"type":["string","null"]},"duration_ns":{"type":["integer","null"],"format":"int64"},"exit_code":{"type":["integer","null"],"format":"int64"},"observed_by":{"description":"The sources that observed this command.","type":"array","items":{"type":"string"}}},"required":["record","command","host","started_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('focus.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"FocusFused","description":"A stretch during which a window had keyboard focus, from the compositor''s\nfocus changes and ActivityWatch''s window spans. Focus is exclusive, so\nwhatever the sources call the window, two of them seeing focus begin at\nthe same moment saw the same focus.","type":"object","properties":{"record":{"type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"description":"`None` while the focus holds.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"app":{"description":"The application: the compositor''s window class or ActivityWatch''s app.","type":["string","null"]},"title":{"type":["string","null"]},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","started_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('visit.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"VisitFused","description":"One page visit, from a browser''s own history, a Takeout history export\nand the browser-navigation capture.","type":"object","properties":{"record":{"type":"string"},"url":{"type":"string"},"title":{"type":["string","null"]},"visited_at":{"$ref":"#/$defs/Timestamp"},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","url","visited_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('play.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PlayFused","description":"One play of a track, from a streaming history export and the media\nplayer''s live state (live MPRIS capture and the capture lake).","type":"object","properties":{"record":{"type":"string"},"title":{"type":"string"},"artist":{"type":["string","null"]},"album":{"type":["string","null"]},"player":{"description":"The player that reported it, when a live source saw it.","type":["string","null"]},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"description":"When playback stopped, or the track''s end when only its length is known.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","title","started_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('clipboard.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ClipboardFused","description":"One clipboard or primary-selection change, from live capture and the\ncapture lake.","type":"object","properties":{"record":{"type":"string"},"selection":{"description":"`clipboard` or `primary`.","type":"string"},"text":{"type":["string","null"]},"mime_type":{"type":["string","null"]},"copied_at":{"$ref":"#/$defs/Timestamp"},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","selection","copied_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('notification.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NotificationFused","description":"One desktop notification, from live capture and the capture lake.","type":"object","properties":{"record":{"type":"string"},"app":{"type":"string"},"summary":{"type":"string"},"body":{"type":["string","null"]},"shown_at":{"$ref":"#/$defs/Timestamp"},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","app","summary","shown_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('mail.fused','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MailFused","description":"One mail message, from every mail source that holds it (IMAP, Maildir,\nmbox, Outlook): its `Message-ID` and `Date` are the same wherever it is\nstored.","type":"object","properties":{"record":{"type":"string"},"message_id":{"type":"string"},"subject":{"type":["string","null"]},"from":{"type":"array","items":{"type":"string"}},"thread_id":{"type":["string","null"]},"sent_at":{"description":"The `Date` header.","$ref":"#/$defs/Timestamp"},"observed_by":{"type":"array","items":{"type":"string"}}},"required":["record","message_id","from","sent_at","observed_by"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['record']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('shell.session','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ShellSession","description":"A run of shell commands on one host with no gap longer than the session\nrule''s gap between one command''s end and the next command''s start. Derived\nfrom fused commands; identified by host and start (its end moves as it\ngrows; its start does not), so a session that grows replaces its earlier reading.","type":"object","properties":{"host":{"type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"description":"The latest recorded end of any member command (a command without a\nduration counts as a point).","$ref":"#/$defs/Timestamp"},"day":{"description":"The logical day the session belongs to (`YYYY-MM-DD`).","type":"string"},"commands":{"type":"integer","format":"uint32","minimum":0},"failed":{"description":"Commands that exited non-zero.","type":"integer","format":"uint32","minimum":0},"cwds":{"description":"Working directories in first-seen order.","type":"array","items":{"type":"string"}}},"required":["host","started_at","ended_at","day","commands","failed","cwds"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['host','started_at']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('state.interval','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"StateInterval","description":"A span during which some state held: a focused window, a workspace, an\nActivityWatch bout. Derived from transitions by the\ninterval derivation. Identified by its start evidence; the end may still\nbe unknown (`ended_at` is `None` while the state holds).","type":"object","properties":{"interval_id":{"description":"`<state kind>:<subject>:<start record location or start time>`.","type":"string"},"state_kind":{"type":"string"},"subject_id":{"type":["string","null"]},"label":{"type":["string","null"]},"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"start_event_type":{"type":"string"},"end_event_type":{"description":"What ended it: the next transition, a fence, a stop, or the observed\nduration (`None` while open).","type":["string","null"]},"attributes":{"type":"object","additionalProperties":{"type":"string"}}},"required":["interval_id","state_kind","started_at","start_event_type"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['interval_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('metric.figure','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MetricFigure","description":"One metric over one civil hour or logical day: how many input events it\ncounted and the metric''s number for them, in total or for one value of a\nbreakdown field. Hourly figures are computed from the metric''s input\nevents, daily ones from the day''s hourly figures. A period nothing was\ncounted in has no figure; whether that means zero or unobserved depends on\nwhether the sources were observing, which is read with the figures.","type":"object","properties":{"metric":{"description":"The metric''s name (`shell.commands`).","type":"string"},"grain":{"description":"`hour` or `day`.","type":"string"},"period_start":{"$ref":"#/$defs/Timestamp"},"period_end":{"$ref":"#/$defs/Timestamp"},"day":{"description":"The logical day the period belongs to (`YYYY-MM-DD`).","type":"string"},"dimension":{"description":"The breakdown field (`cwd`), and the value this figure counts for;\nboth empty for the total.","type":"string"},"dimension_value":{"type":"string"},"value":{"description":"The metric''s number; `None` where it is undefined (a ratio of zero\ncommands with a known exit code).","type":["number","null"],"format":"double"},"numerator":{"description":"A ratio''s parts, summed from hours to the day.","type":["number","null"],"format":"double"},"denominator":{"type":["number","null"],"format":"double"},"rows":{"description":"Input events counted.","type":"integer","format":"uint64","minimum":0}},"required":["metric","grain","period_start","period_end","day","dimension","dimension_value","rows"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['metric','grain','period_start','dimension','dimension_value']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('health.figure','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"HealthFigure","description":"Figures over one series of health points in one civil hour or logical\nday: how many points started in the period and, for each numeric value\nposition, their count, sum, minimum and maximum. Hourly figures are\ncomputed from the points, daily ones from the day''s hourly figures.","type":"object","properties":{"grain":{"description":"`hour` or `day`.","type":"string"},"period_start":{"$ref":"#/$defs/Timestamp"},"period_end":{"$ref":"#/$defs/Timestamp"},"day":{"description":"The logical day the period belongs to (`YYYY-MM-DD`).","type":"string"},"provider":{"type":"string"},"category":{"description":"The points'' data type.","type":"string"},"series":{"description":"Where the points came from: a Fit data source.","type":"string"},"points":{"type":"integer","format":"uint64","minimum":0},"values":{"type":"array","items":{"$ref":"#/$defs/FigureValue"}}},"required":["grain","period_start","period_end","day","provider","category","series","points","values"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"FigureValue":{"description":"One numeric value position of a series'' points, over a period.","type":"object","properties":{"position":{"type":"integer","format":"uint32","minimum":0},"count":{"type":"integer","format":"uint64","minimum":0},"sum":{"type":"number","format":"double"},"min":{"type":"number","format":"double"},"max":{"type":"number","format":"double"}},"required":["position","count","sum","min","max"]}}}'::jsonb,'fields',ARRAY['grain','period_start','provider','series']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('browser.visit','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BrowserVisit","description":"One visit in a Chromium-family browser''s `History` database (`visits`\njoined with `urls`). Chromium writes the visit when it starts and fills in\nits duration when the page is left, so a newer reading replaces the live\none.","type":"object","properties":{"profile":{"description":"The profile directory, such as `google-chrome/Default`.","type":"string"},"visit_id":{"description":"Chromium''s `visits.id`.","type":"integer","format":"int64"},"url":{"description":"`None` when the visit''s `urls` row is gone.","type":["string","null"]},"title":{"type":["string","null"]},"visited_at":{"$ref":"#/$defs/Timestamp"},"from_visit":{"description":"The visit this one came from (a link click); `None` when it had none.","type":["integer","null"],"format":"int64"},"transition":{"description":"Chromium''s page transition as stored: the core type in the low byte,\ntransition flags above it.","type":"integer","format":"int64"},"duration_us":{"description":"How long the page stayed open; `None` while it is still open (0).","type":["integer","null"],"format":"int64"},"extra":{"description":"Columns this parser does not know yet, kept by name.","type":"object","additionalProperties":true}},"required":["profile","visit_id","visited_at","transition"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['profile','visit_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('browser.url','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BrowserUrl","description":"One row of a Chromium-family browser''s `urls` table: a page and its\nrunning counts, updated in place as it is visited again.","type":"object","properties":{"profile":{"type":"string"},"url_id":{"description":"Chromium''s `urls.id`.","type":"integer","format":"int64"},"url":{"type":"string"},"title":{"type":["string","null"]},"visit_count":{"type":"integer","format":"int64"},"typed_count":{"type":"integer","format":"int64"},"last_visited_at":{"description":"`None` when Chromium stored 0 (never).","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"hidden":{"type":"boolean"},"extra":{"type":"object","additionalProperties":true}},"required":["profile","url_id","url","visit_count","typed_count","hidden"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['profile','url_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('browser.history_entry','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BrowserHistoryEntry","description":"One entry of a Google Takeout Chrome history export. It has no ID, so the\nURL and time identify it, and a later export of the same entry is a repeat.","type":"object","properties":{"url":{"type":"string"},"title":{"type":["string","null"]},"visited_at":{"$ref":"#/$defs/Timestamp"},"page_transition":{"description":"Takeout''s `page_transition`, such as `LINK` or `TYPED`.","type":["string","null"]},"client_id":{"description":"The synced device the visit came from.","type":["string","null"]},"favicon_url":{"type":["string","null"]},"extra":{"type":"object","additionalProperties":true}},"required":["url","visited_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['url','visited_at']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('music.played','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MusicPlayed","description":"One play of a track, episode or audiobook chapter from a Spotify streaming\nhistory export. Spotify records when playback stopped (`ts`, or `endTime`\nin the older account-data export) and how long it played; the start is\nderived from those two.","type":"object","properties":{"started_at":{"$ref":"#/$defs/Timestamp"},"ended_at":{"$ref":"#/$defs/Timestamp"},"played_ms":{"type":"integer","format":"int64"},"track_uri":{"type":["string","null"]},"track_name":{"type":["string","null"]},"artist_name":{"type":["string","null"]},"album_name":{"type":["string","null"]},"episode_uri":{"type":["string","null"]},"episode_name":{"type":["string","null"]},"show_name":{"type":["string","null"]},"audiobook_title":{"type":["string","null"]},"audiobook_chapter_title":{"type":["string","null"]},"platform":{"type":["string","null"]},"conn_country":{"type":["string","null"]},"reason_start":{"type":["string","null"]},"reason_end":{"type":["string","null"]},"shuffle":{"type":["boolean","null"]},"skipped":{"description":"Spotify''s own skip flag; `None` when the export does not say.","type":["boolean","null"]},"offline":{"type":["boolean","null"]},"incognito_mode":{"type":["boolean","null"]},"extra":{"description":"Fields this parser does not model (`ip_addr`, `offline_timestamp`, new\nfields), kept by name.","type":"object","additionalProperties":true}},"required":["started_at","ended_at","played_ms"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['ended_at','played_ms','track_uri','episode_uri','track_name','artist_name']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('bookmark.saved','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BookmarkSaved","description":"A saved bookmark in a bookmarking service (Raindrop). The service''s ID is\nthe identity, so an edited or moved bookmark is a newer reading; one in the\ntrash is removed at the source.","type":"object","properties":{"service":{"type":"string"},"native_id":{"type":"string"},"url":{"type":"string"},"title":{"type":["string","null"]},"note":{"type":["string","null"]},"excerpt":{"type":["string","null"]},"folder":{"description":"The collection or folder it is filed in.","type":["string","null"]},"tags":{"type":"array","items":{"type":"string"}},"created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"updated_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"cover":{"type":["string","null"]},"highlights":{"description":"Highlighted passages, as the service exported them."},"favorite":{"type":["boolean","null"]},"trashed_at":{"description":"When it went to the trash. The trash export gives no time, so the last\nupdate stands for it.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"extra":{"type":"object","additionalProperties":true}},"required":["service","native_id","url","tags"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('note.document','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NoteDocument","description":"A note file in a notes vault (Obsidian, plain Markdown folders). The vault\nand the path inside it identify it; an edit is a newer reading, and a file\nmissing from a completed scan is removed at the source.","type":"object","properties":{"vault":{"type":"string"},"path":{"description":"Relative to the vault root.","type":"string"},"text":{"description":"The file''s text; `None` for a removed file.","type":["string","null"]},"size":{"type":"integer","format":"uint64","minimum":0},"modified_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"removed_at":{"description":"When a completed scan first found the file gone.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"title":{"description":"Absent for a removed file and for a note without one.","type":["string","null"]},"note_id":{"description":"The exact front-matter string, including an explicitly empty ID.","type":["string","null"]},"tags":{"description":"Sorted string tags from the parsed header and known body. An invalid\nfront_matter means header tags remain unknown.","type":["array","null"],"items":{"type":"string"}},"wikilinks":{"type":["array","null"],"items":{"type":"string"}},"front_matter":{"anyOf":[{"$ref":"#/$defs/NoteFrontMatter"},{"type":"null"}]}},"required":["vault","path","size"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"NoteFrontMatter":{"description":"The parsed YAML header, separate from the exact original note text.","oneOf":[{"type":"object","properties":{"state":{"type":"string","const":"absent"}},"required":["state"]},{"type":"object","properties":{"state":{"type":"string","const":"parsed"},"value":true},"required":["state","value"]},{"type":"object","properties":{"state":{"type":"string","const":"invalid"},"kind":{"$ref":"#/$defs/NoteFrontMatterError"},"line":{"description":"One-based coordinates in the note, when the parser supplies them.","type":["integer","null"],"format":"uint64","minimum":0},"column":{"type":["integer","null"],"format":"uint64","minimum":0}},"required":["state","kind"]}]},"NoteFrontMatterError":{"description":"Structural diagnostics contain no copied note text or YAML snippets.","type":"string","enum":["yaml","unsupported_value","limit","unclosed"]}}}'::jsonb,'fields',ARRAY['vault','path']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('chat.message','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ChatMessage","description":"One line of a chat log (WeeChat IRC logs): a message, an action, or a\njoin, part, quit or other notice. Logs have no message IDs and only grow, so\nthe record location is the identity.","type":"object","properties":{"buffer":{"description":"The log''s buffer, such as `irc.libera.#lesswrong`.","type":"string"},"sent_at":{"$ref":"#/$defs/Timestamp"},"nick":{"description":"The sender''s nick, without its mode prefix.","type":["string","null"]},"prefix":{"description":"The mode prefix shown before the nick (`@`, `+`), if any.","type":["string","null"]},"text":{"type":"string"},"kind":{"$ref":"#/$defs/ChatLineKind"}},"required":["buffer","sent_at","text","kind"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"ChatLineKind":{"oneOf":[{"type":"string","enum":["message","action","join","part","quit","notice"]},{"description":"Server and client lines without a sender.","type":"string","const":"system"}]}}}'::jsonb,'location',ARRAY[]::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('mail.message','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MailMessage","description":"One email message, from an mbox file or a Maildir. The `Message-ID` header\nidentifies it (a hash of the raw message when the header is missing), and a\nlater export with different labels is a newer reading.","type":"object","properties":{"message_id":{"type":"string"},"date":{"description":"The `Date` header; `None` when missing or unreadable.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"from":{"type":"array","items":{"type":"string"}},"to":{"type":"array","items":{"type":"string"}},"cc":{"type":"array","items":{"type":"string"}},"subject":{"type":["string","null"]},"in_reply_to":{"type":["string","null"]},"references":{"type":"array","items":{"type":"string"}},"labels":{"description":"Gmail''s `X-Gmail-Labels`, split.","type":"array","items":{"type":"string"}},"thread_id":{"description":"Gmail''s `X-GM-THRID`.","type":["string","null"]},"text":{"description":"The first `text/plain` part, decoded.","type":["string","null"]},"html_only":{"description":"True when the message has HTML but no plain text part.","type":"boolean"},"attachments":{"type":"array","items":{"$ref":"#/$defs/MailAttachment"}},"size":{"description":"The raw message''s size in bytes.","type":"integer","format":"uint64","minimum":0}},"required":["message_id","from","to","cc","references","labels","html_only","attachments","size"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"MailAttachment":{"type":"object","properties":{"filename":{"type":["string","null"]},"content_type":{"type":"string"},"size":{"type":"integer","format":"uint64","minimum":0}},"required":["content_type","size"]}}}'::jsonb,'fields',ARRAY['message_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.session','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Session","description":"One AI session: a conversation or agent run in one tool.","type":"object","properties":{"session":{"description":"`<origin>:<native id>`, such as `claude-code:7f3a…`.","type":"string"},"origin":{"description":"The tool that wrote it: `claude-code`, `codex`, `chatgpt`, ….","type":"string"},"kind":{"description":"`main`, `subagent`, `sidechain` or `compaction`.","type":"string"},"title":{"type":["string","null"]},"cwd":{"description":"Working directories in the order the session used them.","type":"array","items":{"type":"string"}},"repo":{"description":"The repository, as the session names it or as its directory resolves.","type":["string","null"]},"branch":{"type":["string","null"]},"tool_version":{"description":"The tool''s version.","type":["string","null"]},"mode":{"description":"How the tool ran it, when not interactively (`bg`).","type":["string","null"]},"machine":{"description":"The machine whose files hold it (`/etc/machine-id`), when known.","type":["string","null"]},"started":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"last_activity":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"links":{"description":"How it relates to other sessions, as their records state it.","type":"array","items":{"$ref":"#/$defs/SessionLink"}}},"additionalProperties":false,"required":["session","origin","kind","cwd","links"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"SessionLink":{"description":"A relationship between two sessions. Lineage is a reference between\nsessions, never event ancestry.","type":"object","properties":{"kind":{"description":"`fork`, `spawn`, `continuation` or `copy`.","type":"string"},"parent":{"type":"string"},"child":{"type":"string"},"at":{"description":"The parent''s message the child branched from or was spawned by.","type":["string","null"]},"call_id":{"description":"The parent''s tool call that spawned the child.","type":["string","null"]}},"additionalProperties":false,"required":["kind","parent","child"]}}}'::jsonb,'fields',ARRAY['session']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.message','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Message","description":"One message of a session, stored once where it originated. Its text is\nwhat people and models wrote, so it is guarded.","type":"object","properties":{"message":{"type":"string"},"session":{"type":"string"},"parent":{"description":"The message it replies to, when the source records it.","type":["string","null"]},"role":{"description":"`user`, `assistant` or `system`.","type":"string"},"written_by":{"description":"Who wrote it: `human`, `model`, `harness` or `unknown`.","type":"string"},"prompt_kind":{"description":"A typed prompt''s kind: `prose`, `command`, `harness` or `model`.","type":["string","null"]},"at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"model":{"type":["string","null"]},"text":{"description":"Its text blocks, joined by blank lines. Tool inputs and outputs stay\nin the material.","type":"string"},"usage":{"$ref":"#/$defs/Usage"},"cost_nusd":{"description":"Polylogue''s cost of the message in billionths of a dollar; unknown\nwhen absent.","type":["integer","null"],"format":"int64"},"stop_reason":{"type":["string","null"]},"duration_ms":{"type":["integer","null"],"format":"uint64","minimum":0},"attachments":{"type":"array","items":{"$ref":"#/$defs/Attachment"}},"copies":{"description":"The other records that carry a version of this message (the same\nmessage in an export and in a live file). The event''s own location is\nthe version Polylogue shows.","type":"array","items":{"$ref":"#/$defs/RecordRef"}}},"additionalProperties":false,"required":["message","session","role","written_by","text","usage","attachments","copies"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"Usage":{"description":"Token counts as the source reported them; unknown when absent.","type":"object","properties":{"input":{"type":["integer","null"],"format":"uint64","minimum":0},"cached_input":{"type":["integer","null"],"format":"uint64","minimum":0},"cache_write":{"type":["integer","null"],"format":"uint64","minimum":0},"output":{"type":["integer","null"],"format":"uint64","minimum":0},"reasoning":{"type":["integer","null"],"format":"uint64","minimum":0}},"additionalProperties":false},"Attachment":{"description":"An image or file a message carried.","type":"object","properties":{"name":{"type":["string","null"]},"media_type":{"type":["string","null"]},"size":{"type":["integer","null"],"format":"uint64","minimum":0},"blob":{"description":"`blake3:<hex>` of the bytes, when they were stored.","type":["string","null"]},"direction":{"description":"`input` (to the model), `output` (from it) or `unknown`.","type":"string"}},"additionalProperties":false,"required":["direction"]},"RecordRef":{"description":"A record in a material: another version of a message, or a tool call''s\noutput.","type":"object","properties":{"material":{"$ref":"#/$defs/MaterialId"},"anchor":{"description":"Byte position of the record in that material.","type":"integer","format":"uint64","minimum":0}},"additionalProperties":false,"required":["material","anchor"]},"MaterialId":{"description":"Immutable stored bytes that events cite.","type":"string","format":"uuid"}}}'::jsonb,'fields',ARRAY['message']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.tool_call','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ToolCall","description":"One tool call and how it ended. Its arguments and output stay in the\nmaterial: `result` names the record holding the output.","type":"object","properties":{"call":{"description":"`tool:<session>#<call id>`, Polylogue''s reference to the call.","type":"string"},"session":{"type":"string"},"message":{"description":"The message that made the call.","type":"string"},"tool":{"type":"string"},"action":{"description":"`shell`, `code`, `file_read`, `file_write`, `file_edit`, `search`,\n`web`, `subagent`, `mcp` or `other`.","type":"string"},"command":{"description":"The shell command, when the call runs one.","type":["string","null"]},"path":{"description":"The file it reads or changes, when it names one.","type":["string","null"]},"outcome":{"description":"`ok`, `error` or `unknown`.","type":"string"},"outcome_reason":{"type":["string","null"]},"exit_code":{"type":["integer","null"],"format":"int64"},"at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"result":{"description":"The record holding the call''s output.","anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}]}},"additionalProperties":false,"required":["call","session","message","tool","action","outcome"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"RecordRef":{"description":"A record in a material: another version of a message, or a tool call''s\noutput.","type":"object","properties":{"material":{"$ref":"#/$defs/MaterialId"},"anchor":{"description":"Byte position of the record in that material.","type":"integer","format":"uint64","minimum":0}},"additionalProperties":false,"required":["material","anchor"]},"MaterialId":{"description":"Immutable stored bytes that events cite.","type":"string","format":"uuid"}}}'::jsonb,'fields',ARRAY['call']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.turn','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Turn","description":"One turn: a person''s prompts and what answered them, so other sources can\nbe read during it.","type":"object","properties":{"turn":{"description":"Its first prompt''s message ID.","type":"string"},"session":{"type":"string"},"start":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"end":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"prompts":{"description":"The prompt messages, in order.","type":"array","items":{"type":"string"}},"answer":{"description":"The last model message of the turn.","type":["string","null"]},"slash_command":{"description":"Whether the turn opened with a slash command.","type":"boolean"},"tool_calls":{"type":"integer","format":"uint64","minimum":0},"errors":{"type":"integer","format":"uint64","minimum":0},"input_tokens":{"type":["integer","null"],"format":"uint64","minimum":0},"output_tokens":{"type":["integer","null"],"format":"uint64","minimum":0},"cost_nusd":{"type":["integer","null"],"format":"int64"},"abandoned":{"description":"The session''s last turn, with no answer.","type":"boolean"}},"additionalProperties":false,"required":["turn","session","prompts","slash_command","tool_calls","errors","abandoned"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['turn']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.delivery','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Delivery","description":"Context Polylogue prepared for a model or the operator: what it held and\nwhat it left out. The text itself is in the record''s material.","type":"object","properties":{"delivery":{"type":"string"},"recipient_kind":{"description":"`session` or `operator`.","type":"string"},"recipient_id":{"type":["string","null"]},"sender":{"description":"`hook`, `mcp`, `cli`, `ping` or `signal`.","type":"string"},"event":{"description":"`session_start`, `resume`, `compaction`, `recall`, ….","type":"string"},"cwd":{"type":["string","null"]},"at":{"$ref":"#/$defs/Timestamp"},"content_hash":{"description":"`blake3:<hex>` of the delivered text.","type":"string"},"bytes":{"type":"integer","format":"uint64","minimum":0},"refs":{"description":"References included, in order.","type":"array","items":{"type":"string"}},"left_out":{"type":"array","items":{"$ref":"#/$defs/LeftOut"}}},"additionalProperties":false,"required":["delivery","recipient_kind","sender","event","at","content_hash","bytes","refs","left_out"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"LeftOut":{"type":"object","properties":{"what":{"type":"string"},"reason":{"type":"string"}},"additionalProperties":false,"required":["what","reason"]}}}'::jsonb,'fields',ARRAY['delivery']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.delivery_outcome','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"DeliveryOutcome","description":"What happened to a prepared delivery.","type":"object","properties":{"delivery":{"type":"string"},"what":{"description":"`delivered`, `failed`, `not_sent` or `used`.","type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"detail":{"type":["string","null"]}},"additionalProperties":false,"required":["delivery","what","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['delivery','what','at']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.note','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Note","description":"A note, tag, title, judgment, saved query or other assertion a person or\nagent wrote about something. A revision is a new note with the same\n`first_note`; a withdrawal is a note of kind `withdrawal`.","type":"object","properties":{"note":{"type":"string"},"first_note":{"description":"The first note of its revisions; the note itself for a first note.","type":"string"},"kind":{"type":"string"},"key":{"type":["string","null"]},"value":{"type":["string","null"]},"author":{"description":"`operator`, an agent session ID, `agent` or `script`.","type":"string"},"machine":{"type":"string"},"created_at":{"$ref":"#/$defs/Timestamp"},"valid_until":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"targets":{"description":"What it is about: `session:…`, `message:…`, `tool:…`, ….","type":"array","items":{"type":"string"}},"relations":{"type":"array","items":{"$ref":"#/$defs/NoteRelation"}}},"additionalProperties":false,"required":["note","first_note","kind","author","machine","created_at","targets","relations"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"NoteRelation":{"type":"object","properties":{"kind":{"description":"`revises`, `withdraws`, `answers`, `challenges`, ….","type":"string"},"other":{"type":"string"}},"additionalProperties":false,"required":["kind","other"]}}}'::jsonb,'fields',ARRAY['note']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.setting','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Setting","description":"One value of a Polylogue setting; a change is a new record.","type":"object","properties":{"setting":{"type":"string"},"machine":{"description":"The machine it applies to, or `*` for every machine.","type":"string"},"key":{"type":"string"},"value":{"type":"string"},"author":{"type":"string"},"set_at":{"$ref":"#/$defs/Timestamp"}},"additionalProperties":false,"required":["setting","machine","key","value","author","set_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['setting']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.kept_result','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"KeptResult","description":"A query''s answer kept as it was, cited as `result:<id>`.","type":"object","properties":{"result":{"type":"string"},"name":{"type":["string","null"]},"query":{"type":"string"},"ran_at":{"$ref":"#/$defs/Timestamp"},"read_at":{"description":"What its read transaction read (the query''s resolved time)."},"rows":{"description":"The rows it returned."}},"additionalProperties":false,"required":["result","query","ran_at","read_at","rows"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['result']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('polylogue.excision','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Excision","description":"The operator''s request to remove something from Polylogue for good.","type":"object","properties":{"excision":{"type":"string"},"target":{"description":"What it removed: `input:<id>`, `session:<id>` or `document:<id>`.","type":"string"},"reason":{"type":["string","null"]},"created_at":{"$ref":"#/$defs/Timestamp"}},"additionalProperties":false,"required":["excision","target","created_at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['excision']::text[],'suppress_repeat');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('action.recorded','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ActionRecorded","description":"One entry of an account''s activity log (Google My Activity): a search, a\nvisit, an app action. The instant is the identity across exports: each\nexport writes its times in the zone of the export day, and restates titles,\nso neither the time text nor the title can be.","type":"object","properties":{"service":{"description":"The service heading the entry: `Search`, `Chrome`, `Maps`.","type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"verb":{"description":"The words before the link (`Searched for`, `Visited`); a field, never\npart of the identity, since Google rewords it between exports.","type":["string","null"]},"title":{"description":"The linked text, or the whole first line when nothing is linked.","type":"string"},"title_url":{"type":["string","null"]},"unlinked_text":{"description":"For an entry without a link, its first line; the identity then rests\non it beside the instant, so two unlinked actions in one second stay\napart.","type":["string","null"]},"lines":{"description":"Lines between the title and the time.","type":"array","items":{"type":"string"}},"products":{"type":"array","items":{"type":"string"}},"locations":{"type":"array","items":{"type":"string"}},"details":{"type":"array","items":{"type":"string"}},"zone_label":{"description":"The time zone label the export printed (`UTC`, `CEST`); the export\nday''s zone, kept for reference.","type":"string"}},"required":["service","at","title","lines","products","locations","details","zone_label"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','at','title_url','unlinked_text']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('video.watched','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"VideoWatched","description":"A video watched on a video service (YouTube watch history).","type":"object","properties":{"service":{"type":"string"},"video_id":{"description":"`None` when the entry links no video: a removed video Google lists\nwithout a link, or a link to something other than a video.","type":["string","null"]},"watched_at":{"$ref":"#/$defs/Timestamp"},"url":{"type":["string","null"]},"title":{"description":"`None` when the export names no title: the video is gone and Google\nwrites `Watched <url>`. A later export that drops a title an earlier\none had does not erase it (`keep_known`).","type":["string","null"]},"channel":{"type":["string","null"]},"channel_url":{"type":["string","null"]},"products":{"type":"array","items":{"type":"string"}},"details":{"type":"array","items":{"type":"string"}}},"required":["service","watched_at","products","details"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','video_id','watched_at']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('video.searched','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"VideoSearched","description":"A search on a video service (YouTube search history).","type":"object","properties":{"service":{"type":"string"},"searched_at":{"$ref":"#/$defs/Timestamp"},"query":{"type":"string"},"url":{"type":["string","null"]},"products":{"type":"array","items":{"type":"string"}}},"required":["service","searched_at","query","products"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','searched_at','query']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('note.observed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NoteObserved","description":"A note kept in a notes service (Google Keep). Keep writes no note ID and\nnames files after titles, so the creation time is the identity; a later\nedit is a newer reading.","type":"object","properties":{"service":{"type":"string"},"created_at":{"$ref":"#/$defs/Timestamp"},"edited_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"title":{"type":["string","null"]},"text":{"type":["string","null"]},"items":{"description":"Checklist items, in order.","type":"array","items":{"$ref":"#/$defs/NoteItem"}},"labels":{"type":"array","items":{"type":"string"}},"color":{"type":["string","null"]},"pinned":{"type":["boolean","null"]},"archived":{"type":["boolean","null"]},"trashed_at":{"description":"The edit time when the note is in the trash; the export gives no time\nof trashing.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"attachments":{"description":"Attached files, by the name Takeout wrote them under.","type":"array","items":{"type":"string"}},"extra":{"type":"object","additionalProperties":true}},"required":["service","created_at","items","labels","attachments"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"NoteItem":{"type":"object","properties":{"text":{"type":"string"},"checked":{"type":"boolean"}},"required":["text","checked"]}}}'::jsonb,'fields',ARRAY['service','created_at']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('task.revised','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"TaskRevised","description":"A task in a task list (Google Tasks); a later export''s reading with a newer\n`updated` replaces it.","type":"object","properties":{"service":{"type":"string"},"task_id":{"type":"string"},"list_id":{"type":"string"},"list_title":{"type":["string","null"]},"title":{"type":["string","null"]},"notes":{"type":["string","null"]},"status":{"type":["string","null"]},"parent":{"type":["string","null"]},"created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"updated_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"due":{"type":["string","null"]},"completed_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"deleted_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"extra":{"type":"object","additionalProperties":true}},"required":["service","task_id","list_id"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','task_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('purchase.observed','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PurchaseObserved","description":"An order, install, library item or purchase an account store recorded\n(Google Play, Purchases). The time is the wrapped item''s own field.","type":"object","properties":{"service":{"type":"string"},"record_kind":{"description":"The wrapper the item came in: `orderHistory`, `install`,\n`purchaseHistory`, `libraryDoc`.","type":"string"},"native_id":{"description":"The provider''s ID, or a hash of the item when it has none.","type":"string"},"at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"title":{"type":["string","null"]},"item":true},"required":["service","record_kind","native_id","item"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','record_kind','native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('calendar.event','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"CalendarEvent","description":"One event of a calendar (RFC 5545 `VEVENT`), from an export or a calendar\nAPI. A recurring series is one event with its rule; a changed occurrence is\nits own event with a recurrence ID. Expanding a rule into occurrences is a\nderivation.","type":"object","properties":{"calendar":{"description":"The calendar it belongs to (the export''s calendar name).","type":"string"},"uid":{"type":"string"},"recurrence_id":{"description":"For one changed occurrence of a series, the original start it replaces,\nas written.","type":["string","null"]},"summary":{"type":["string","null"]},"description":{"type":["string","null"]},"location":{"type":["string","null"]},"start":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"end":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"all_day":{"description":"A date without a time: the event spans whole days.","type":"boolean"},"zone":{"description":"The zone the times were written in (`Europe/Warsaw`, `UTC`), or\n`floating` for local times the export ties to no zone, read in the\nconfigured zone.","type":"string"},"status":{"type":["string","null"]},"rrule":{"type":["string","null"]},"exdates":{"type":"array","items":{"type":"string"}},"organizer":{"type":["string","null"]},"attendees":{"type":"array","items":{"type":"string"}},"created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"last_modified":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"sequence":{"type":["integer","null"],"format":"int64"},"cancelled_at":{"description":"The last-modified time when the status is `CANCELLED`.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"extra":{"description":"Properties not modelled above, by name, as written.","type":"object","additionalProperties":true}},"required":["calendar","uid","all_day","zone","exdates","attendees"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['calendar','uid','recurrence_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('account.row','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"AccountRow","type":"object","properties":{"service":{"type":"string"},"table":{"type":"string"},"native_id":{"type":"string"},"at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"values":{"type":"object","additionalProperties":true},"untyped":{"type":"boolean","default":true}},"required":["service","table","native_id","values"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','table','native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('location.sample','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"LocationSample","description":"A location fix an account recorded (Google Location History): where the\ndevice was, how sure it was, and what it thought the operator was doing.\nThe device and the instant identify it across exports.","type":"object","properties":{"provider":{"type":"string"},"device":{"description":"The export''s device tag; `None` in older exports, which carry none.","type":["string","null"]},"at":{"$ref":"#/$defs/Timestamp"},"latitude":{"type":"number","format":"double"},"longitude":{"type":"number","format":"double"},"accuracy_m":{"description":"Meters, as the provider reported it.","type":["number","null"],"format":"double"},"altitude_m":{"type":["number","null"],"format":"double"},"velocity_mps":{"type":["number","null"],"format":"double"},"heading_deg":{"type":["number","null"],"format":"double"},"activity":{"description":"Activity guesses with their confidences, as exported."},"extra":{"type":"object","additionalProperties":true}},"required":["provider","at","latitude","longitude"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['provider','device','at']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('conversation.message','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"ConversationMessage","description":"A message in a direct or group conversation of a messaging service\n(Facebook Messenger, SMS). Exports carry no thread or message ID that\nsurvives between them, so a message is the thread (its participants), its\ntime and its sender; the same message read from another export or input is\nthe same occurrence.","type":"object","properties":{"service":{"type":"string"},"thread":{"description":"The thread''s participants, sorted and joined by `|`.","type":"string"},"thread_name":{"description":"The name the export gave the thread.","type":["string","null"]},"participants":{"type":"array","items":{"type":"string"}},"sender":{"type":"string"},"sent_at":{"$ref":"#/$defs/Timestamp"},"text":{"type":["string","null"]},"kind":{"description":"The service''s message type (`text`, `media`, `call`).","type":["string","null"]},"media":{"description":"Media and attachments, by the path the export wrote them under.","type":"array","items":{"type":"string"}},"reactions":{"type":"array","items":true},"message_id":{"description":"The service''s message ID, when the export has one.","type":["string","null"]},"unsent_at":{"description":"When the sender unsent it; the export gives no time, so the send time\nstands for it.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["service","thread","participants","sender","sent_at","media","reactions"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','thread','sent_at','sender']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('book.status','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"BookStatus","description":"A book shelved or read in a reading tracker (Goodreads). Dates are days,\nso these serve long-horizon interest, not daily behaviour.","type":"object","properties":{"service":{"type":"string"},"book_id":{"type":"string"},"action":{"description":"`shelved` (added) or `read` (finished).","type":"string"},"at":{"description":"The day, at midnight UTC; the export gives no time of day.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"title":{"type":"string"},"author":{"type":["string","null"]},"additional_authors":{"type":["string","null"]},"isbn":{"type":["string","null"]},"isbn13":{"type":["string","null"]},"my_rating":{"description":"The operator''s rating, 1-5; `None` when unrated (the export writes 0).","type":["integer","null"],"format":"int64"},"average_rating":{"type":["number","null"],"format":"double"},"publisher":{"type":["string","null"]},"binding":{"type":["string","null"]},"pages":{"type":["integer","null"],"format":"int64"},"year_published":{"type":["integer","null"],"format":"int64"},"original_year":{"type":["integer","null"],"format":"int64"},"shelves":{"type":"array","items":{"type":"string"}},"exclusive_shelf":{"type":["string","null"]},"review":{"type":["string","null"]},"private_notes":{"type":["string","null"]},"read_count":{"type":["integer","null"],"format":"int64"},"owned_copies":{"type":["integer","null"],"format":"int64"}},"required":["service","book_id","action","title","shelves"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','book_id','action']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('health.record','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"HealthRecord","type":"object","properties":{"provider":{"type":"string"},"category":{"type":"string"},"native_id":{"type":"string"},"start":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"end":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"offset_minutes":{"type":["integer","null"],"format":"int32"},"values":{"$ref":"#/$defs/HealthValues"},"events":{"type":"array","items":{"$ref":"#/$defs/HealthEvent"},"default":[]},"untyped":{"type":"boolean","default":false},"unknown_fields":{"type":"array","items":{"type":"string"},"default":[]}},"required":["provider","category","native_id","values"],"$defs":{"Timestamp":{"type":"string","format":"date-time"},"HealthValues":{"description":"Known source categories select their fields before decoding. A malformed\nknown field is an error, never a reason to read the row as unknown.","anyOf":[{"$ref":"#/$defs/SleepSession"},{"$ref":"#/$defs/SleepNoise"},{"$ref":"#/$defs/Fit"},{"$ref":"#/$defs/Stress"},{"$ref":"#/$defs/Steps"},{"$ref":"#/$defs/Hrv"},{"$ref":"#/$defs/HeartRate"},{"$ref":"#/$defs/Oxygen"},{"$ref":"#/$defs/Respiratory"},{"$ref":"#/$defs/SkinTemperature"},{"$ref":"#/$defs/Sleep"},{"$ref":"#/$defs/SleepCombined"},{"$ref":"#/$defs/SleepStage"},{"$ref":"#/$defs/Snoring"},{"$ref":"#/$defs/Movement"},{"$ref":"#/$defs/Nap"},{"$ref":"#/$defs/Vitality"},{"$ref":"#/$defs/Weight"},{"$ref":"#/$defs/Floors"},{"$ref":"#/$defs/Mood"},{"$ref":"#/$defs/ActivityDay"},{"$ref":"#/$defs/Calories"},{"$ref":"#/$defs/Ecg"},{"type":"object","additionalProperties":true}]},"SleepSession":{"type":"object","properties":{"tz_column":{"type":["string","null"]},"scheduled":{"type":["string","null"]},"comment":{"type":["string","null"]},"hours":{"type":["number","null"],"format":"double"},"rating":{"type":["number","null"],"format":"double"},"framerate":{"type":["number","null"],"format":"double"},"snore":{"type":["number","null"],"format":"double"},"noise":{"type":["number","null"],"format":"double"},"cycles":{"type":["number","null"],"format":"double"},"deep_sleep":{"type":["number","null"],"format":"double"},"len_adjust":{"type":["number","null"],"format":"double"},"geo":{"type":["string","null"]},"actigraphy":{"type":["array","null"],"items":{"type":"array","prefixItems":[{"type":["string","null"]},{"type":["number","null"],"format":"double"}],"minItems":2,"maxItems":2}}},"additionalProperties":true},"SleepNoise":{"type":"object","properties":{"noise":{"type":["array","null"],"items":{"type":["number","null"],"format":"double"}}},"additionalProperties":true},"Fit":{"type":"object","properties":{"fitValue":{"type":["array","null"],"items":{"$ref":"#/$defs/FitValue"}},"modifiedTimeMillis":{"anyOf":[{"$ref":"#/$defs/Scalar"},{"type":"null"}]},"originDataSourceId":{"type":["string","null"]}},"additionalProperties":true},"FitValue":{"type":"object","properties":{"value":{"anyOf":[{"$ref":"#/$defs/FitValue"},{"type":"null"}]},"intVal":{"type":["number","null"],"format":"double"},"fpVal":{"type":["number","null"],"format":"double"},"stringVal":{"type":["string","null"]},"mapVal":{"type":["array","null"],"items":{"$ref":"#/$defs/MapEntry"}}},"additionalProperties":true},"MapEntry":{"type":"object","properties":{"key":{"type":["string","null"]},"value":{"anyOf":[{"$ref":"#/$defs/FitValue"},{"type":"null"}]}},"additionalProperties":true},"Scalar":{"description":"CSV normalization preserves numbers and numeric-looking text separately.","anyOf":[{"type":"number","format":"double"},{"type":"string"}]},"Stress":{"type":"object","properties":{"start_time":{"anyOf":[{"$ref":"#/$defs/Scalar"},{"type":"null"}]},"end_time":{"anyOf":[{"$ref":"#/$defs/Scalar"},{"type":"null"}]},"day_time":{"anyOf":[{"$ref":"#/$defs/Scalar"},{"type":"null"}]},"create_time":{"anyOf":[{"$ref":"#/$defs/Scalar"},{"type":"null"}]},"time_offset":{"anyOf":[{