INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('post.published','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"PostPublished","description":"A post, comment or link the operator published.","type":"object","properties":{"service":{"type":"string"},"kind":{"description":"`entry`, `entry_comment`, `link`, `link_comment`, `post`, `comment`.","type":"string"},"native_id":{"type":"string"},"created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"title":{"type":["string","null"]},"body":{"type":["string","null"]},"url":{"type":["string","null"]},"parent":{"description":"What it replies to or belongs to (the entry or link a comment is on).","type":["string","null"]},"community":{"description":"The community or tags it was filed under.","type":["string","null"]},"tags":{"type":"array","items":{"type":"string"}},"score":{"type":["integer","null"],"format":"int64"},"extra":{"type":"object","additionalProperties":true}},"required":["service","kind","native_id","tags"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','kind','native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('vote.cast','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"VoteCast","description":"A vote the operator cast on someone''s post. Exports list votes without the\ntime they were cast, so the event time is unknown; the target''s own time is\na field.","type":"object","properties":{"service":{"type":"string"},"target_kind":{"type":"string"},"target_id":{"type":"string"},"direction":{"description":"`up` or `down`.","type":"string"},"cast_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"target_created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"target_title":{"type":["string","null"]},"target_url":{"type":["string","null"]},"target_author":{"type":["string","null"]},"withdrawn_at":{"description":"Set when the export records the vote as withdrawn (Reddit''s `none`).","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"extra":{"type":"object","additionalProperties":true}},"required":["service","target_kind","target_id","direction"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','target_kind','target_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('notification.received','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"NotificationReceived","description":"A notification an online community sent the operator (Wykop: a new entry\nor link under a tag the operator observes). The service''s notification ID\nis the identity; a later reading that marks it read is newer.","type":"object","properties":{"service":{"type":"string"},"native_id":{"type":"string"},"kind":{"description":"The service''s notification type (`new_entry_with_observed_tag`).","type":"string"},"created_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"read":{"type":["boolean","null"]},"target":{"description":"What it points at, as `entry:<id>` or `link:<id>`.","type":["string","null"]},"target_url":{"type":["string","null"]},"actor":{"description":"Who caused it.","type":["string","null"]},"channel":{"description":"The tag or channel it came through.","type":["string","null"]},"extra":{"type":"object","additionalProperties":true}},"required":["service","native_id","kind"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['service','native_id']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('account.setting','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"AccountSetting","description":"One entry of an account setting the operator keeps at a service, such as a\nblocked user, tag or domain. The setting and its value are the identity;\nexports give no time the operator set it.","type":"object","properties":{"service":{"type":"string"},"setting":{"description":"`blacklist/users`, `blacklist/tags`, `blacklist/domains`.","type":"string"},"value":{"type":"string"},"extra":{"type":"object","additionalProperties":true}},"required":["service","setting","value"]}'::jsonb,'fields',ARRAY['service','setting','value']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('operator_log.entry','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"LogEntry","description":"One entry of the operator''s quick-note log. The entry is its place in the\nlog; an edit to it is a newer reading.","type":"object","properties":{"written_at":{"description":"Unknown for an entry headed by a label instead of a time\n(`**SPECIAL:**`).","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"label":{"description":"The bold heading when it is a label, not a time.","type":["string","null"]},"text":{"description":"The entry''s text, continuation lines included.","type":"string"}},"required":["text"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'location',ARRAY[]::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('steering.row','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"SteeringRow","description":"One steering row, identified by its table and record ID, with typed known\nvalues.","type":"object","properties":{"table":{"$ref":"#/$defs/Table"},"record_id":{"type":"string"},"at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"values":{"$ref":"#/$defs/SteeringValues"}},"additionalProperties":false,"required":["table","record_id","values"],"$defs":{"Table":{"type":"string","enum":["commitments","activities","reviews"]},"Timestamp":{"type":"string","format":"date-time"},"SteeringValues":{"description":"A closed choice of known row shapes. Deserialization is selected by the table,\nnever by trying these variants against the same untagged object.","anyOf":[{"$ref":"#/$defs/Commitment"},{"$ref":"#/$defs/Activity"},{"$ref":"#/$defs/Review"}]},"Commitment":{"description":"A commitment and forecast, including the written outcome.","type":"object","properties":{"id":{"type":"string"},"text":{"type":["string","null"]},"created_at":{"type":["string","null"]},"window_start":{"type":["string","null"]},"window_end":{"type":["string","null"]},"forecast_p":{"type":["number","null"],"format":"double"},"status":{"anyOf":[{"$ref":"#/$defs/CommitmentStatus"},{"type":"null"}]},"outcome_at":{"type":["string","null"]},"outcome_note":{"type":["string","null"]},"activity_id":{"type":["string","null"]},"review_id":{"type":["string","null"]}},"additionalProperties":false,"required":["id"]},"CommitmentStatus":{"type":"string","enum":["open","done","missed","retired"]},"Activity":{"description":"An undated activity or experiment in the steering catalog.","type":"object","properties":{"id":{"type":"string"},"name":{"type":["string","null"]},"kind":{"anyOf":[{"$ref":"#/$defs/ActivityKind"},{"type":"null"}]},"est_minutes":{"type":["integer","null"],"format":"int64"},"energy_tier":{"