INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.copy','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"FileCopy","description":"A file seen in a library root by a scan. Identified by host and path: a\nchanged file is a newer reading, a file missing from a completed scan is\nremoved at the source. The bytes are named by `content` whether or not the\nscan kept them.","type":"object","properties":{"host":{"type":"string"},"root":{"description":"The library root the scan walked.","type":"string"},"path":{"description":"The file''s absolute path.","type":"string"},"content":{"description":"`blake3:<hex>`, the content store''s name for the bytes.","type":"string"},"size":{"type":"integer","format":"uint64","minimum":0},"sha256":{"description":"Hex digests other catalogues name files by (Hydrus, boorus).","type":"string"},"md5":{"type":"string"},"media_type":{"description":"Sniffed from the bytes; `application/octet-stream` when unknown. A file\nSinex cannot read is still stored and described.","type":"string"},"width":{"type":["integer","null"],"format":"uint32","minimum":0},"height":{"type":["integer","null"],"format":"uint32","minimum":0},"duration_ms":{"type":["integer","null"],"format":"uint64","minimum":0},"stored":{"description":"Whether the scan stored the bytes in the content store (a root can be\nindexed by reference only).","type":"boolean"},"device":{"type":["integer","null"],"format":"uint64","minimum":0},"inode":{"type":["integer","null"],"format":"uint64","minimum":0},"modified_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]},"moved_from":{"description":"The path this file had before: the same file (device and inode) with\nthe same bytes was seen there by an earlier walk. Evidence of a rename.","type":["string","null"]},"previous_content":{"description":"The bytes this path held before, when the same file changed in place.\nEvidence that an item continued with new bytes.","type":["string","null"]},"vanished_at":{"description":"When a completed scan first found the file gone.","anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["host","root","path","content","size","sha256","md5","media_type","stored"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['host','path']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.item','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Item","description":"One revision of an item. The live reading is the current revision; the\narchived readings are its history. New bytes make a new revision only\nwhen continuity was shown (a library operation, or the same file changing\nin place); an unrelated copy of the same bytes is a different item.","type":"object","properties":{"item":{"description":"Opaque: independent of digests, paths, labels and event IDs.","type":"string"},"revision":{"type":"integer","format":"uint32","minimum":0},"replaces":{"description":"The revision this one replaces.","type":["integer","null"],"format":"uint32","minimum":0},"content":{"description":"The original rendition''s bytes, `blake3:<hex>`.","type":"string"},"media_type":{"type":"string"},"copies":{"description":"Copies that belong to the item, as `host:path`.","type":"array","items":{"type":"string"}},"label":{"description":"A human label; the file name at intake when nothing better is known.","type":["string","null"]},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["item","revision","content","media_type","copies","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['item']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.rendition','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Rendition","description":"Bytes standing for an item revision: its original, or something made\nfrom it. A preview never answers a request for the original.","type":"object","properties":{"rendition":{"type":"string"},"item":{"type":"string"},"revision":{"type":"integer","format":"uint32","minimum":0},"role":{"$ref":"#/$defs/RenditionRole"},"content":{"type":"string"},"media_type":{"type":"string"},"width":{"type":["integer","null"],"format":"uint32","minimum":0},"height":{"type":["integer","null"],"format":"uint32","minimum":0},"duration_ms":{"type":["integer","null"],"format":"uint64","minimum":0},"made_from":{"description":"The rendition it was made from; `None` for an original.","type":["string","null"]},"made_with":{"description":"How it was made: the tool and its settings.","type":"object","additionalProperties":true},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["rendition","item","revision","role","content","media_type","by","at"],"$defs":{"RenditionRole":{"type":"string","enum":["original","crop","preview","transcode"]},"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['rendition']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.assignment','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Assignment","description":"One value given to one field of a target: a tag (`field = \"tag\"`), or a\nproperty. A property can be set to empty (`value = None`), which stops\nfallback to lower levels. Withdrawing an assignment is a newer reading of\nit with `withdrawn_at` set.","type":"object","properties":{"assignment":{"type":"string"},"target":{"$ref":"#/$defs/Target"},"field":{"description":"`tag`, or the property''s name.","type":"string"},"value":{"type":["string","null"]},"level":{"$ref":"#/$defs/Level"},"source_ref":{"description":"Where an imported value came from: a sidecar file, a post URL.","type":["string","null"]},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["assignment","target","field","level","by","at"],"$defs":{"Target":{"description":"What an assignment, entry or view is about: an item (following its\nrevisions), one revision, one rendition, or a part of a rendition.","type":"object","properties":{"item":{"type":"string"},"revision":{"description":"Fixed revision; `None` follows the item.","type":["integer","null"],"format":"uint32","minimum":0},"rendition":{"type":["string","null"]},"part":{"description":"A selector inside the rendition: `t=12.5-40` (seconds, half-open) or\n`xywh=10,10,200,120` (pixels).","type":["string","null"]}},"required":["item"]},"Level":{"description":"Who an assigned value comes from, highest first in the selection policy.","oneOf":[{"description":"The operator''s own value; wins over everything, an empty one included.","type":"string","const":"override"},{"description":"Brought in from another application or site.","type":"string","const":"import"},{"description":"A model''s suggestion.","type":"string","const":"proposal"}]},"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['assignment']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.collection','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Collection","description":"A collection: an ordered list of entries, optionally with a saved query that\noffers suggestions. A fixed selection is a collection without a query whose\nentries were added from a query''s results.","type":"object","properties":{"collection":{"type":"string"},"name":{"type":"string"},"saved_query":{"type":["string","null"]},"selected_from":{"description":"The query the entries were selected from, for a fixed selection.","type":["string","null"]},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["collection","name","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['collection']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.entry','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Entry","description":"One entry in a collection. Each insertion is a new entry, so the same item\ncan appear twice; removing an entry withdraws it and keeps it inspectable.","type":"object","properties":{"entry":{"type":"string"},"collection":{"type":"string"},"target":{"description":"The item, with the revision fixed when it was added.","$ref":"#/$defs/Target"},"position":{"description":"Sort position; an entry inserted between two takes a value between\ntheirs.","type":"number","format":"double"},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["entry","collection","target","position","by","at"],"$defs":{"Target":{"description":"What an assignment, entry or view is about: an item (following its\nrevisions), one revision, one rendition, or a part of a rendition.","type":"object","properties":{"item":{"type":"string"},"revision":{"description":"Fixed revision; `None` follows the item.","type":["integer","null"],"format":"uint32","minimum":0},"rendition":{"type":["string","null"]},"part":{"description":"A selector inside the rendition: `t=12.5-40` (seconds, half-open) or\n`xywh=10,10,200,120` (pixels).","type":["string","null"]}},"required":["item"]},"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['entry']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.rating','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Rating","description":"A rating on a named scale (`stars`, `favourite`), one per rater.","type":"object","properties":{"item":{"type":"string"},"scale":{"type":"string"},"value":{"type":"number","format":"double"},"of":{"description":"The top of the scale (5 stars, 1 for a like).","type":"number","format":"double"},"level":{"$ref":"#/$defs/Level"},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["item","scale","value","of","level","by","at"],"$defs":{"Level":{"description":"Who an assigned value comes from, highest first in the selection policy.","oneOf":[{"description":"The operator''s own value; wins over everything, an empty one included.","type":"string","const":"override"},{"description":"Brought in from another application or site.","type":"string","const":"import"},{"description":"A model''s suggestion.","type":"string","const":"proposal"}]},"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['item','scale','by']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.comparison','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Comparison","description":"One pairwise judgement: `winner` is better than `loser` on `scale`. A\nranking is fitted from all of them.","type":"object","properties":{"comparison":{"type":"string"},"scale":{"type":"string"},"winner":{"type":"string"},"loser":{"type":"string"},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"},"withdrawn_at":{"anyOf":[{"$ref":"#/$defs/Timestamp"},{"type":"null"}]}},"required":["comparison","scale","winner","loser","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['comparison']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.view','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"View","description":"One time something was opened for viewing or playing. The target is fixed\nwhen the request is made.","type":"object","properties":{"view":{"type":"string"},"target":{"$ref":"#/$defs/Target"},"player":{"description":"The program it was handed to.","type":"string"},"started_at":{"$ref":"#/$defs/Timestamp"},"seconds":{"description":"How long it was open; `None` while it still is, or when unknown.","type":["number","null"],"format":"double"},"count":{"description":"Imported view counts carry how many views the record stands for.","type":"integer","format":"uint32","minimum":0},"level":{"$ref":"#/$defs/Level"},"by":{"type":"string"}},"required":["view","target","player","started_at","count","level","by"],"$defs":{"Target":{"description":"What an assignment, entry or view is about: an item (following its\nrevisions), one revision, one rendition, or a part of a rendition.","type":"object","properties":{"item":{"type":"string"},"revision":{"description":"Fixed revision; `None` follows the item.","type":["integer","null"],"format":"uint32","minimum":0},"rendition":{"type":["string","null"]},"part":{"description":"A selector inside the rendition: `t=12.5-40` (seconds, half-open) or\n`xywh=10,10,200,120` (pixels).","type":["string","null"]}},"required":["item"]},"Timestamp":{"type":"string","format":"date-time"},"Level":{"description":"Who an assigned value comes from, highest first in the selection policy.","oneOf":[{"description":"The operator''s own value; wins over everything, an empty one included.","type":"string","const":"override"},{"description":"Brought in from another application or site.","type":"string","const":"import"},{"description":"A model''s suggestion.","type":"string","const":"proposal"}]}}}'::jsonb,'fields',ARRAY['view']::text[],'replace_when_newer');
INSERT INTO registry.event_types(name,payload_schema,key_kind,key_fields,replace_rule) VALUES ('library.dismissal','{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Dismissal","description":"A collection suggestion the operator dismissed; remembered for that\ncollection and query revision.","type":"object","properties":{"collection":{"type":"string"},"item":{"type":"string"},"query":{"description":"The saved query''s text when the suggestion was seen.","type":"string"},"by":{"type":"string"},"at":{"$ref":"#/$defs/Timestamp"}},"required":["collection","item","query","by","at"],"$defs":{"Timestamp":{"type":"string","format":"date-time"}}}'::jsonb,'fields',ARRAY['collection','item','query']::text[],'replace_when_newer');
